window.QUESTION_TOPICS = window.QUESTION_TOPICS || {};
window.QUESTION_TOPICS["content/06_tools_build_debug/04_performance.md"] = [{"id":"content/06_tools_build_debug/04_performance.md:db323d891309fa1c:1","question":"<p>(L1, T) Что такое profiling и чем он отличается от benchmarking?</p>\n","answer":"<p><strong>Ответ:</strong> Profiling показывает, где расходуются ресурсы; benchmarking измеряет результат заданной нагрузки. Профиль объясняет измеренное замедление.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L1","line":33},{"id":"content/06_tools_build_debug/04_performance.md:77e216aa0450fb0f:1","question":"<p>(L1, T) Зачем нужен CPU profiling?</p>\n","answer":"<p><strong>Ответ:</strong> Он локализует участки и пути вызовов с большим расходом CPU, чтобы оптимизировать измеренный bottleneck.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L1","line":39},{"id":"content/06_tools_build_debug/04_performance.md:a1eeabf914183cd4:1","question":"<p>(L1, T) Что такое hotspot?</p>\n","answer":"<p><strong>Ответ:</strong> Hotspot — участок с большой долей выбранной метрики: samples, CPU time или аллокаций. Метрику нужно указывать.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L1","line":45},{"id":"content/06_tools_build_debug/04_performance.md:bffe47d1b7420e29:1","question":"<p>(L1, T) Почему “самая медленная функция” не всегда корень проблемы?</p>\n","answer":"<p><strong>Ответ:</strong> Большое время может определяться частотой вызовов, входными данными или ожиданием. Проверяют caller и причину нагрузки.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L1","line":51},{"id":"content/06_tools_build_debug/04_performance.md:3ab1dfbbab0aa30e:1","question":"<p>(L1, T) Что такое sampling profiler?</p>\n","answer":"<p><strong>Ответ:</strong> Он периодически снимает состояние исполнения и статистически оценивает распределение работы; короткие функции могут не попасть в samples.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L1","line":57},{"id":"content/06_tools_build_debug/04_performance.md:70b7913951921162:1","question":"<p>(L1, T) Что такое instrumentation profiler?</p>\n","answer":"<p><strong>Ответ:</strong> Он добавляет измерительный код на выбранные события или границы функций; точность событий оплачивается накладными расходами.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L1","line":63},{"id":"content/06_tools_build_debug/04_performance.md:5a2979db4e8d9d0f:1","question":"<p>(L1, T) Что такое wall-clock time и CPU time?</p>\n","answer":"<p><strong>Ответ:</strong> Wall time — прошедшее реальное время; CPU time — время исполнения на CPU. Сумма CPU time потоков может превышать wall time.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L1","line":69},{"id":"content/06_tools_build_debug/04_performance.md:7be27de75e66499e:1","question":"<p>(L1, T) Что такое user time и system time?</p>\n","answer":"<p><strong>Ответ:</strong> User time учитывает исполнение пользовательского кода, system time — работу ядра от имени процесса.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L1","line":75},{"id":"content/06_tools_build_debug/04_performance.md:adf97654d2239d84:1","question":"<p>(L1, P) Как измерить общее время выполнения программы в Linux?</p>\n","answer":"<p><strong>Ответ:</strong> Запустить <code>/usr/bin/time -v ./app</code>; сравнить elapsed, user и system time на одинаковом входе.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L1","line":81},{"id":"content/06_tools_build_debug/04_performance.md:6dab2e14a4b26bbf:1","question":"<p>(L1, T) Почему без измерений оптимизация — это угадывание?</p>\n","answer":"<p><strong>Ответ:</strong> Без baseline неизвестны ни реальный bottleneck, ни размер эффекта; изменения могут ускорить редко выполняемый код.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L1","line":87},{"id":"content/06_tools_build_debug/04_performance.md:ad67f9e87a975237:1","question":"<p>(L2, T) Что такое <code>perf</code> и для чего он используется?</p>\n","answer":"<p><strong>Ответ:</strong> Linux perf собирает counters, samples и tracing events; доступность зависит от ядра, PMU и разрешений.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":96},{"id":"content/06_tools_build_debug/04_performance.md:56aebf79c8ff5ddf:1","question":"<p>(L2, P) Как запустить <code>perf stat</code> для программы?</p>\n","answer":"<p><strong>Ответ:</strong> <code>perf stat -- ./app</code> собирает сводку событий за запуск; для повторов используют <code>perf stat -r 5 -- ./app</code>.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":102},{"id":"content/06_tools_build_debug/04_performance.md:f8cdc9c0e30a5cd2:1","question":"<p>(L2, P) Как запустить <code>perf record</code> и посмотреть отчет?</p>\n","answer":"<p><strong>Ответ:</strong> <code>perf record -g -- ./app</code>, затем <code>perf report</code>; корректность стеков зависит от unwind metadata и выбранного метода.</p>\n<p><strong>Пример:</strong> На Linux для приложения с debug info и подходящей поддержкой DWARF unwinding:</p>\n<pre><code class=\"language-bash\">perf record -F 99 --call-graph dwarf -o perf.data -- ./app input.dat\nperf report -i perf.data --stdio\n</code></pre>\n<p><strong>Типичная ошибка:</strong> Анализировать короткий startup вместо steady-state фазы или использовать symbols другой сборки.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":108},{"id":"content/06_tools_build_debug/04_performance.md:7d5cbcbc0e80b4c9:1","question":"<p>(L2, T) Что такое sampling frequency?</p>\n","answer":"<p><strong>Ответ:</strong> Это целевая частота samples, например <code>-F 99</code>; рост частоты повышает детализацию и overhead, возможны throttling и потери.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":123},{"id":"content/06_tools_build_debug/04_performance.md:41433d855e572b73:1","question":"<p>(L2, T) Что такое call graph profiling?</p>\n","answer":"<p><strong>Ответ:</strong> Профиль сохраняет цепочки вызовов, позволяя связать горячую функцию с контекстом её использования.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":129},{"id":"content/06_tools_build_debug/04_performance.md:1425a38d10c5e46e:1","question":"<p>(L2, P) Как понять, какая функция потребляет CPU?</p>\n","answer":"<p><strong>Ответ:</strong> Снять <code>perf record -g -- ./app</code>, затем посмотреть self/children в <code>perf report</code> и callers горячих функций.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":135},{"id":"content/06_tools_build_debug/04_performance.md:b41c9a6e7781ce90:1","question":"<p>(L2, D) Почему top/htop недостаточно для анализа производительности?</p>\n","answer":"<p><strong>Ответ:</strong> Они показывают загрузку процессов, но обычно не объясняют конкретные функции, cache misses и пути ожидания.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":141},{"id":"content/06_tools_build_debug/04_performance.md:d6966b04a1b181c2:1","question":"<p>(L2, T) Что такое <code>gprof</code>?</p>\n","answer":"<p><strong>Ответ:</strong> GNU gprof анализирует данные профилирования инструментированного приложения: flat profile и call graph.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":147},{"id":"content/06_tools_build_debug/04_performance.md:e0728ec07161cb51:1","question":"<p>(L2, P) Как собрать программу для <code>gprof</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Компилировать и линковать с <code>-pg</code>, например <code>gcc -pg -g app.c -o app</code>; затем выполнить программу.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":153},{"id":"content/06_tools_build_debug/04_performance.md:2ba4702a9e5189be:1","question":"<p>(L2, T) В чем ограничения <code>gprof</code> по сравнению с <code>perf</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Классический gprof требует instrumentation и ограничен в анализе потоков, ядра, ожиданий и hardware events.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":159},{"id":"content/06_tools_build_debug/04_performance.md:4d6bbd9953ce7563:1","question":"<p>(L3, T) Как <code>perf</code> получает samples на Linux?</p>\n","answer":"<p><strong>Ответ:</strong> Ядро через perf events сохраняет samples при событиях PMU либо программных событиях; режим и payload настраиваются.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":168},{"id":"content/06_tools_build_debug/04_performance.md:449f091a69999955:1","question":"<p>(L3, T) Что такое PMU (Performance Monitoring Unit)?</p>\n","answer":"<p><strong>Ответ:</strong> PMU — аппаратный блок измерения событий CPU, например retired instructions и cache events; набор зависит от модели процессора.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":174},{"id":"content/06_tools_build_debug/04_performance.md:61170dec58734a82:1","question":"<p>(L3, T) Разница hardware counters vs software events?</p>\n","answer":"<p><strong>Ответ:</strong> Hardware events исходят от PMU; software events формирует ядро, например context switches и page faults.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":180},{"id":"content/06_tools_build_debug/04_performance.md:d607bcac66b01003:1","question":"<p>(L3, P) Как использовать <code>perf top</code> для live-анализа?</p>\n","answer":"<p><strong>Ответ:</strong> <code>perf top -p PID</code> показывает горячие символы работающего процесса; для причин нужны стеки и репрезентативный интервал.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":186},{"id":"content/06_tools_build_debug/04_performance.md:c0cfcc2d8ff77ca3:1","question":"<p>(L3, P) Как собрать flamegraph из <code>perf</code> данных?</p>\n","answer":"<p><strong>Ответ:</strong> Получить стеки через <code>perf record -g</code>, вывести <code>perf script</code>, затем обработать <code>stackcollapse-perf.pl</code> и <code>flamegraph.pl</code> из FlameGraph.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":192},{"id":"content/06_tools_build_debug/04_performance.md:c6e8b6fd40cd0c6e:1","question":"<p>(L3, T) Что такое inclusive time и exclusive/self time?</p>\n","answer":"<p><strong>Ответ:</strong> Inclusive включает вложенные вызовы; self относится непосредственно к функции. Samples не всегда являются точным временем.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":198},{"id":"content/06_tools_build_debug/04_performance.md:d0f0b80c5eccc270:1","question":"<p>(L3, D) Почему горячая функция может быть “жертвой”, а не причиной проблемы?</p>\n","answer":"<p><strong>Ответ:</strong> Allocator может быть горячим из-за лишних объектов у caller; исправлять следует источник ненужной работы.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":204},{"id":"content/06_tools_build_debug/04_performance.md:78e5bd14fd145cde:1","question":"<p>(L3, T) Что показывает flamegraph?</p>\n","answer":"<p><strong>Ответ:</strong> Агрегированное распределение стеков по выбранному весу, часто числу CPU samples; это не временная шкала.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":210},{"id":"content/06_tools_build_debug/04_performance.md:32142684ebbe5528:1","question":"<p>(L3, D) Как читать flamegraph правильно?</p>\n","answer":"<p><strong>Ответ:</strong> Ищут широкие пути снизу вверх, проверяют caller и self; ширина отражает вес, цвет обычно не кодирует стоимость.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":216},{"id":"content/06_tools_build_debug/04_performance.md:1924d5ed7d2dd1e6:1","question":"<p>(L3, D) Почему “широкий фрейм” на flamegraph не всегда значит, что код надо оптимизировать именно там?</p>\n","answer":"<p><strong>Ответ:</strong> Родитель включает потомков, а широкий leaf может обслуживать избыточное число запросов; нужна причинная проверка.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":222},{"id":"content/06_tools_build_debug/04_performance.md:3e992ee7a963370b:1","question":"<p>(L4, T) Как sampling bias влияет на выводы из профилирования?</p>\n","answer":"<p><strong>Ответ:</strong> Редкие или периодические события могут недопредставляться; проверяют объём выборки, lost samples и альтернативные события.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L4","line":231},{"id":"content/06_tools_build_debug/04_performance.md:3f2d329205b2f3bb:1","question":"<p>(L4, D) Как диагностировать performance cliff, который проявляется только на production-нагрузке?</p>\n","answer":"<p><strong>Ответ:</strong> Воспроизвести размер данных, concurrency и saturation; сопоставить профили, очередь, throttling, память и latency до порога.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L4","line":237},{"id":"content/06_tools_build_debug/04_performance.md:5837dcb8db068f04:1","question":"<p>(L4, S) Как встроить CPU profiling в инженерный workflow команды?</p>\n","answer":"<p><strong>Ответ:</strong> Определить сценарии, baseline, владельцев и формат артефактов; снимать профиль при регрессии и проверять эффект исправления.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L4","line":243},{"id":"content/06_tools_build_debug/04_performance.md:09142e6874b82bd8:1","question":"<p>(L4, D) Как отличить CPU-bound проблему от lock contention, IO wait или scheduler issue?</p>\n","answer":"<p><strong>Ответ:</strong> Сравнить CPU/wall time, runnable/wait states, scheduler traces и стеки ожидания; on-CPU samples не объясняют весь wall time.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L4","line":249},{"id":"content/06_tools_build_debug/04_performance.md:542ee359f4deaecc:1","question":"<p>(L4, S) Как строить reproducible CPU profiling pipeline для large-scale C++ сервиса?</p>\n","answer":"<p><strong>Ответ:</strong> Фиксировать commit, бинарник/symbols, workload, CPU/kernel, flags и команды; хранить raw profile и несколько независимых повторов.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L4","line":255},{"id":"content/06_tools_build_debug/04_performance.md:f617f80e085e7833:1","question":"<p>(L1, T) Что показывает <code>perf stat</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Сводные значения выбранных событий, время запуска и производные отношения; это не профиль функций.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L1","line":266},{"id":"content/06_tools_build_debug/04_performance.md:c35ed9764f9b369e:1","question":"<p>(L1, P) Как посмотреть instructions, cycles, branches?</p>\n","answer":"<p><strong>Ответ:</strong> <code>perf stat -e instructions,cycles,branches,branch-misses -- ./app</code>; проверить поддержку событий и долю времени измерения.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L1","line":272},{"id":"content/06_tools_build_debug/04_performance.md:fa741adb71ac001f:1","question":"<p>(L1, T) Что такое IPC?</p>\n","answer":"<p><strong>Ответ:</strong> Instructions per cycle: retired instructions / cycles. IPC сравнивают в контексте CPU и workload, без универсального целевого значения.</p>\n<p><strong>Пример:</strong> 2 миллиарда instructions / 1 миллиард cycles = IPC 2. Это не означает, что программа быстрее приложения с IPC 1: последнее могло выполнять меньше полезных для результата инструкций.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L1","line":278},{"id":"content/06_tools_build_debug/04_performance.md:a2678c52cdab2572:1","question":"<p>(L1, T) Почему высокий CPU usage не всегда означает плохую производительность?</p>\n","answer":"<p><strong>Ответ:</strong> Полезная параллельная работа тоже загружает CPU; важны throughput, latency и стоимость единицы результата.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L1","line":286},{"id":"content/06_tools_build_debug/04_performance.md:09a4a1d71037b45e:1","question":"<p>(L1, P) Как профилировать конкретный PID через <code>perf</code>?</p>\n","answer":"<p><strong>Ответ:</strong> <code>perf record -p PID -g -- sleep 10</code>; видимость процесса и разрешения должны позволять attachment.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L1","line":292},{"id":"content/06_tools_build_debug/04_performance.md:9d1179ea63c000c2:1","question":"<p>(L2, T) Что такое <code>perf record</code> и <code>perf report</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Record сохраняет samples в perf.data, report агрегирует их по символам и цепочкам вызовов.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":301},{"id":"content/06_tools_build_debug/04_performance.md:743f8f15a6942119:1","question":"<p>(L2, P) Как включить call graph в <code>perf record</code>?</p>\n","answer":"<p><strong>Ответ:</strong> <code>perf record --call-graph dwarf -- ./app</code> либо <code>--call-graph fp</code> при сохранённых frame pointers.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":307},{"id":"content/06_tools_build_debug/04_performance.md:6f977b3de9bc7e1e:1","question":"<p>(L2, D) Почему <code>perf</code> может не показывать symbols?</p>\n","answer":"<p><strong>Ответ:</strong> Возможны stripped binary, отсутствующие debug packages, несовпадающие build IDs или недоступные mappings и kernel symbols.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":313},{"id":"content/06_tools_build_debug/04_performance.md:abb85831154b657e:1","question":"<p>(L2, D) Почему без frame pointers/call graph качество профиля хуже?</p>\n","answer":"<p><strong>Ответ:</strong> Без корректного unwinding теряется caller context; leaf hotspot виден, но источник вызовов определить труднее.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":319},{"id":"content/06_tools_build_debug/04_performance.md:9d4b59ef9ca6e144:1","question":"<p>(L2, P) Как использовать <code>perf annotate</code>?</p>\n","answer":"<p><strong>Ответ:</strong> После записи выполнить <code>perf annotate --stdio</code>; нужны совпадающий executable и доступный disassembly, для строк — debug info.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":325},{"id":"content/06_tools_build_debug/04_performance.md:caaa36e79b9ea887:1","question":"<p>(L2, T) Что такое CPU migrations и context switches?</p>\n","answer":"<p><strong>Ответ:</strong> Migration — перенос потока между CPU; context switch — смена исполняемой task. Их частота требует контекста workload.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":331},{"id":"content/06_tools_build_debug/04_performance.md:6c80a32fa02e27cf:1","question":"<p>(L2, P) Как измерить cache-misses через <code>perf stat</code>?</p>\n","answer":"<p><strong>Ответ:</strong> <code>perf stat -e cache-references,cache-misses -- ./app</code>; generic events имеют платформенно зависимое отображение.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":337},{"id":"content/06_tools_build_debug/04_performance.md:965a26273f1b6ed4:1","question":"<p>(L2, D) Как понять по <code>perf</code>, что проблема в branch misprediction?</p>\n","answer":"<p><strong>Ответ:</strong> Сопоставить branch-misses/branches с samples и кодом ветвлений; одного высокого отношения недостаточно для доказательства причины.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":343},{"id":"content/06_tools_build_debug/04_performance.md:ceb07f14f83223a6:1","question":"<p>(L2, T) Что такое stalled cycles?</p>\n","answer":"<p><strong>Ответ:</strong> События задержек продвижения pipeline; определение frontend/backend stall зависит от конкретной PMU.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":349},{"id":"content/06_tools_build_debug/04_performance.md:1e47e38a60b42b6b:1","question":"<p>(L2, D) Как по counters понять, что код упирается не в ALU, а в память?</p>\n","answer":"<p><strong>Ответ:</strong> Проверить memory bandwidth, load latency, cache/TLB misses и IPC; counters служат гипотезой, подтверждаемой изменением доступа.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":355},{"id":"content/06_tools_build_debug/04_performance.md:8769ab9407e9af75:1","question":"<p>(L3, T) Что такое multiplexing counters в <code>perf</code>?</p>\n","answer":"<p><strong>Ответ:</strong> При нехватке аппаратных счётчиков perf переключает события во времени и масштабирует результаты.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":364},{"id":"content/06_tools_build_debug/04_performance.md:4fd6d676b08b68f7:1","question":"<p>(L3, T) Почему counters иногда неточны?</p>\n","answer":"<p><strong>Ответ:</strong> Причины: multiplexing, короткие интервалы, skid, ограничения PMU и непредставительная выборка; смотрят supported events и scaling.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":370},{"id":"content/06_tools_build_debug/04_performance.md:8776b33df8e912ba:1","question":"<p>(L3, P) Как профилировать только user-space или kernel-space?</p>\n","answer":"<p><strong>Ответ:</strong> Добавить event modifier: <code>perf stat -e cycles:u -- ./app</code> либо <code>cycles:k</code>; права на kernel profiling могут ограничиваться.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":376},{"id":"content/06_tools_build_debug/04_performance.md:dbf1d21f3169853c:1","question":"<p>(L3, P) Как сравнивать два <code>perf</code> профиля до/после оптимизации?</p>\n","answer":"<p><strong>Ответ:</strong> Одинаковые workload и окружение, абсолютные времена и samples, затем <code>perf diff</code>; проценты без общего объёма вводят в заблуждение.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":382},{"id":"content/06_tools_build_debug/04_performance.md:09c4c8524dabae05:1","question":"<p>(L3, D) Как интерпретировать высокий LLC miss rate?</p>\n","answer":"<p><strong>Ответ:</strong> Данные часто не находятся в LLC; проверяют working set, NUMA и bandwidth. Miss rate сам по себе не доказывает memory-bound.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":388},{"id":"content/06_tools_build_debug/04_performance.md:1afbfce850806981:1","question":"<p>(L3, D) Как понять, что bottleneck в instruction cache?</p>\n","answer":"<p><strong>Ответ:</strong> Проверить frontend/i-cache events данной PMU, code footprint и горячий asm; сравнить после уменьшения рабочего кода.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":394},{"id":"content/06_tools_build_debug/04_performance.md:5419407c44b3dee8:1","question":"<p>(L3, T) Что такое off-CPU analysis и чем он отличается от обычного CPU profiling?</p>\n","answer":"<p><strong>Ответ:</strong> Off-CPU анализирует время вне исполнения: блокировки, I/O и scheduling; обычный CPU profile видит исполняемые участки.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":400},{"id":"content/06_tools_build_debug/04_performance.md:4e461a766aae2350:1","question":"<p>(L3, D) Как <code>perf</code> помогает найти lock contention?</p>\n","answer":"<p><strong>Ответ:</strong> Сопоставить futex/scheduler traces и blocked stacks; <code>perf lock</code> ориентирован прежде всего на поддерживаемые kernel lock events.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":406},{"id":"content/06_tools_build_debug/04_performance.md:609ff9a1d0a699d1:1","question":"<p>(L3, P) Как анализировать perf data для многопоточного приложения?</p>\n","answer":"<p><strong>Ответ:</strong> Разделять samples по TID/CPU, смотреть распределение работы и shared hotspots; дополнять scheduler/lock tracing.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":412},{"id":"content/06_tools_build_debug/04_performance.md:8990d4fc90c89145:1","question":"<p>(L3, D) Как профилировать короткоживущую программу, которая заканчивается слишком быстро?</p>\n","answer":"<p><strong>Ответ:</strong> Профилировать весь запуск, увеличить полезную нагрузку или повторять процесс; отдельно учитывать startup и прогрев.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":418},{"id":"content/06_tools_build_debug/04_performance.md:b13aa1974fe255ef:1","question":"<p>(L4, S) Как стандартизировать perf-based performance investigations?</p>\n","answer":"<p><strong>Ответ:</strong> Зафиксировать команды, метаданные, критерии репрезентативности, ограничения доступа и шаблон причинного эксперимента.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L4","line":427},{"id":"content/06_tools_build_debug/04_performance.md:d7079a27526acd78:1","question":"<p>(L4, D) Как расследовать нестабильные результаты <code>perf</code> между прогонами?</p>\n","answer":"<p><strong>Ответ:</strong> Проверить фоновые задачи, frequency, thermal throttling, NUMA, page cache и lost samples; чередовать контрольные прогоны.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L4","line":433},{"id":"content/06_tools_build_debug/04_performance.md:1696d9ca4e3be7fe:1","question":"<p>(L4, S) Как сочетать <code>perf</code>, tracing и benchmarks для одного performance incident?</p>\n","answer":"<p><strong>Ответ:</strong> Benchmark измеряет симптом, perf локализует работу CPU, tracing объясняет очереди и ожидания; коррелировать по времени и request ID.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L4","line":439},{"id":"content/06_tools_build_debug/04_performance.md:2af5de9ec5ab7615:1","question":"<p>(L4, D) Как анализировать CPU profile в контейнерах / ограниченных окружениях?</p>\n","answer":"<p><strong>Ответ:</strong> Проверить perf_event_paranoid, capabilities, namespace PID, cgroup quotas и symbol mappings; контейнер не обеспечивает отдельную PMU.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L4","line":445},{"id":"content/06_tools_build_debug/04_performance.md:5e7ce005998241e6:1","question":"<p>(L4, S) Как автоматизировать regression detection по hardware counters?</p>\n","answer":"<p><strong>Ответ:</strong> Использовать стабильные runners, нормализацию на операцию и повторную проверку порога; counters дополняют пользовательские KPI.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L4","line":451},{"id":"content/06_tools_build_debug/04_performance.md:3978cef45cb945f4:1","question":"<p>(L1, T) Как работает <code>gprof</code> на базовом уровне?</p>\n","answer":"<p><strong>Ответ:</strong> Instrumentation учитывает вызовы, sampling оценивает время; gprof строит отчёт по данным gmon.out.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/binutils/docs/gprof/\">GNU gprof</a></p>\n","group":"L1","line":462},{"id":"content/06_tools_build_debug/04_performance.md:02e794a5e7f4f7ed:1","question":"<p>(L1, P) Какие флаги нужны для сборки под <code>gprof</code>?</p>\n","answer":"<p><strong>Ответ:</strong> <code>-pg</code> нужен при компиляции и линковке; <code>-g</code> добавляет исходные строки, но не заменяет instrumentation.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/binutils/docs/gprof/\">GNU gprof</a></p>\n","group":"L1","line":468},{"id":"content/06_tools_build_debug/04_performance.md:3254816973889501:1","question":"<p>(L1, P) Как получить <code>gmon.out</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Запустить инструментированную программу с правом записи в текущий каталог и нормальным завершением; crash может не сохранить профиль.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/binutils/docs/gprof/\">GNU gprof</a></p>\n","group":"L1","line":474},{"id":"content/06_tools_build_debug/04_performance.md:a767c0aa6e8acdc7:1","question":"<p>(L1, P) Как прочитать отчет <code>gprof</code>?</p>\n","answer":"<p><strong>Ответ:</strong> <code>gprof ./app gmon.out</code>; executable должен соответствовать запуску и быть собран с нужной instrumentation.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/binutils/docs/gprof/\">GNU gprof</a></p>\n","group":"L1","line":480},{"id":"content/06_tools_build_debug/04_performance.md:c9a1b7c749754c21:1","question":"<p>(L1, T) Чем flat profile отличается от call graph в <code>gprof</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Flat profile показывает собственную стоимость функций; call graph добавляет связи callers/callees и распределённую стоимость.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/binutils/docs/gprof/\">GNU gprof</a></p>\n","group":"L1","line":486},{"id":"content/06_tools_build_debug/04_performance.md:b25bad0fdc974365:1","question":"<p>(L2, T) В чем ограничения <code>gprof</code> для современных C/C++ приложений?</p>\n","answer":"<p><strong>Ответ:</strong> Inlining, потоки, shared libraries и instrumentation overhead усложняют интерпретацию; нет полного анализа системных ожиданий.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/binutils/docs/gprof/\">GNU gprof</a></p>\n","group":"L2","line":495},{"id":"content/06_tools_build_debug/04_performance.md:c3eee838c71ceaf4:1","question":"<p>(L2, D) Почему <code>gprof</code> плохо подходит для многопоточного кода?</p>\n","answer":"<p><strong>Ответ:</strong> Классическая модель сбора и атрибуции вызовов не даёт надёжной полной картины современного многопоточного исполнения.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/binutils/docs/gprof/\">GNU gprof</a></p>\n","group":"L2","line":501},{"id":"content/06_tools_build_debug/04_performance.md:3ff36111d44fd793:1","question":"<p>(L2, D) Почему <code>gprof</code> может искажать производительность?</p>\n","answer":"<p><strong>Ответ:</strong> Дополнительные вызовы instrumentation меняют instruction/cache footprint и стоимость часто вызываемых функций.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/binutils/docs/gprof/\">GNU gprof</a></p>\n","group":"L2","line":507},{"id":"content/06_tools_build_debug/04_performance.md:ddad27237ecccd28:1","question":"<p>(L2, T) Когда <code>gprof</code> все еще может быть полезен?</p>\n","answer":"<p><strong>Ответ:</strong> Для простого последовательного приложения и учебного анализа call counts при поддерживаемом toolchain.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/binutils/docs/gprof/\">GNU gprof</a></p>\n","group":"L2","line":513},{"id":"content/06_tools_build_debug/04_performance.md:02a36de91953fcb3:1","question":"<p>(L2, D) Почему <code>gprof</code> показывает странные результаты на optimized code?</p>\n","answer":"<p><strong>Ответ:</strong> Inlining, tail calls и переупорядочивание меняют соответствие исходных функций машинному коду; часть функций исчезает.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/binutils/docs/gprof/\">GNU gprof</a></p>\n","group":"L2","line":519},{"id":"content/06_tools_build_debug/04_performance.md:7e678753c2482c68:1","question":"<p>(L3, D) Как отличить артефакты <code>gprof</code> от реальных bottleneck'ов?</p>\n","answer":"<p><strong>Ответ:</strong> Повторить измерение без instrumentation, проверить perf и workload; эффект должен сохраняться по времени и структуре затрат.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/binutils/docs/gprof/\">GNU gprof</a></p>\n","group":"L3","line":528},{"id":"content/06_tools_build_debug/04_performance.md:e0d27c04bee95f67:1","question":"<p>(L3, S) Почему в современной Linux-практике чаще выбирают <code>perf</code>, а не <code>gprof</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Perf позволяет sampling без пересборки и анализ kernel/hardware events; выбор всё равно зависит от доступности окружения.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/binutils/docs/gprof/\">GNU gprof</a></p>\n","group":"L3","line":534},{"id":"content/06_tools_build_debug/04_performance.md:6d7595427f921c26:1","question":"<p>(L3, D) Какие типы профилей <code>gprof</code> принципиально не может дать?</p>\n","answer":"<p><strong>Ответ:</strong> Классический gprof не предоставляет полноценные off-CPU traces, PMU counters и системный scheduler profile.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/binutils/docs/gprof/\">GNU gprof</a></p>\n","group":"L3","line":540},{"id":"content/06_tools_build_debug/04_performance.md:ebf47e7d2286cd54:1","question":"<p>(L3, T) Почему instrumentation-based profiling меняет runtime behavior?</p>\n","answer":"<p><strong>Ответ:</strong> Измерительный код добавляет инструкции, память и синхронизацию, меняя timing и иногда interleavings потоков.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/binutils/docs/gprof/\">GNU gprof</a></p>\n","group":"L3","line":546},{"id":"content/06_tools_build_debug/04_performance.md:f8e7d04e9123191f:1","question":"<p>(L3, D) Как объяснить расхождение между <code>gprof</code> и <code>perf</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Проверить разные сборки, события, интервалы и overhead; CPU samples и инструментированные оценки могут измерять разное.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/binutils/docs/gprof/\">GNU gprof</a></p>\n","group":"L3","line":552},{"id":"content/06_tools_build_debug/04_performance.md:a90cc04bc753894c:1","question":"<p>(L1, T) Что такое flamegraph?</p>\n","answer":"<p><strong>Ответ:</strong> Визуализация агрегированных стеков, где ширина пропорциональна весу стека, например CPU samples.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/brendangregg/FlameGraph\">FlameGraph</a></p>\n","group":"L1","line":563},{"id":"content/06_tools_build_debug/04_performance.md:0e4014d67475a3df:1","question":"<p>(L1, T) Что означает ширина блока на flamegraph?</p>\n","answer":"<p><strong>Ответ:</strong> Долю выбранного веса во всех samples с этим стековым префиксом; это не обязательно duration одного вызова.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/brendangregg/FlameGraph\">FlameGraph</a></p>\n","group":"L1","line":569},{"id":"content/06_tools_build_debug/04_performance.md:598ae6c3677899c4:1","question":"<p>(L1, T) Что означает высота flamegraph?</p>\n","answer":"<p><strong>Ответ:</strong> Глубину стека вызовов, а не длительность или количество запросов.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/brendangregg/FlameGraph\">FlameGraph</a></p>\n","group":"L1","line":575},{"id":"content/06_tools_build_debug/04_performance.md:651f1f226addd0dc:1","question":"<p>(L1, P) Как на базовом уровне использовать flamegraph для поиска hotspot'ов?</p>\n","answer":"<p><strong>Ответ:</strong> Найти широкие пути и leaves, затем проверить соответствующие callers и исходный код.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/brendangregg/FlameGraph\">FlameGraph</a></p>\n","group":"L1","line":581},{"id":"content/06_tools_build_debug/04_performance.md:8208b0b6eca884f2:1","question":"<p>(L1, D) Почему flamegraph не показывает временную последовательность событий?</p>\n","answer":"<p><strong>Ответ:</strong> Одинаковые стеки объединяются, а горизонтальное положение обычно задаётся сортировкой, не временем.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/brendangregg/FlameGraph\">FlameGraph</a></p>\n","group":"L1","line":587},{"id":"content/06_tools_build_debug/04_performance.md:13fe687426719fa6:1","question":"<p>(L2, D) Как отличить self time от вложенных вызовов на flamegraph?</p>\n","answer":"<p><strong>Ответ:</strong> Ширина родителя включает детей; участок без дочерних frames соответствует self samples в обычном CPU flamegraph.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/brendangregg/FlameGraph\">FlameGraph</a></p>\n","group":"L2","line":596},{"id":"content/06_tools_build_debug/04_performance.md:bb5c1137f83206a3:1","question":"<p>(L2, D) Как понять, что у функции “дорогие дети”, а не она сама?</p>\n","answer":"<p><strong>Ответ:</strong> Большая часть ширины покрыта дочерними frames; подтвердить children/self в табличном отчёте.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/brendangregg/FlameGraph\">FlameGraph</a></p>\n","group":"L2","line":602},{"id":"content/06_tools_build_debug/04_performance.md:b8c57f393df70397:1","question":"<p>(L2, P) Как сравнивать two flamegraphs до/после изменений?</p>\n","answer":"<p><strong>Ответ:</strong> Одинаковые нагрузка, длительность и шкала; сравнивать абсолютную стоимость и нормализованный расход на операцию.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/brendangregg/FlameGraph\">FlameGraph</a></p>\n","group":"L2","line":608},{"id":"content/06_tools_build_debug/04_performance.md:5dd639ed36a1ede1:1","question":"<p>(L2, D) Какие типичные ошибки допускают при чтении flamegraph?</p>\n","answer":"<p><strong>Ответ:</strong> Путать ширину с числом вызовов, высоту со временем, цвет с критичностью и агрегированный график с timeline.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/brendangregg/FlameGraph\">FlameGraph</a></p>\n","group":"L2","line":614},{"id":"content/06_tools_build_debug/04_performance.md:1daa644561784bf2:1","question":"<p>(L2, T) Почему flamegraph удобен для больших call stacks?</p>\n","answer":"<p><strong>Ответ:</strong> Он сохраняет caller context и показывает общие префиксы, скрытые в плоском списке функций.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/brendangregg/FlameGraph\">FlameGraph</a></p>\n","group":"L2","line":620},{"id":"content/06_tools_build_debug/04_performance.md:d206f4cb2131c381:1","question":"<p>(L3, D) Как flamegraph помогает обнаружить accidental complexity?</p>\n","answer":"<p><strong>Ответ:</strong> Повторяющиеся цепочки преобразований и wrappers показывают лишнюю работу; подтвердить, что её можно убрать без изменения контракта.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/brendangregg/FlameGraph\">FlameGraph</a></p>\n","group":"L3","line":629},{"id":"content/06_tools_build_debug/04_performance.md:293f2f95eafdc6e6:1","question":"<p>(L3, D) Как по flamegraph заметить чрезмерную аллокацию или dispatch overhead?</p>\n","answer":"<p><strong>Ответ:</strong> Искать allocator, constructors, virtual dispatch и conversion chains; отличать стоимость операции от чрезмерного числа операций.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/brendangregg/FlameGraph\">FlameGraph</a></p>\n","group":"L3","line":635},{"id":"content/06_tools_build_debug/04_performance.md:f36666c4613450b8:1","question":"<p>(L3, D) Как увидеть на flamegraph, что время уходит в STL/allocator/runtime, а не в business logic?</p>\n","answer":"<p><strong>Ответ:</strong> Посмотреть широкие ветви std/allocator/runtime и перейти к первому прикладному caller, создающему эту нагрузку.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/brendangregg/FlameGraph\">FlameGraph</a></p>\n","group":"L3","line":641},{"id":"content/06_tools_build_debug/04_performance.md:e4cf13cc624d0948:1","question":"<p>(L3, P) Как строить differential flamegraph?</p>\n","answer":"<p><strong>Ответ:</strong> Свернуть стеки baseline и candidate, обработать <code>difffolded.pl</code>, затем <code>flamegraph.pl</code>; согласовать нормализацию.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/brendangregg/FlameGraph\">FlameGraph</a></p>\n","group":"L3","line":647},{"id":"content/06_tools_build_debug/04_performance.md:46927f0bc653be2a:1","question":"<p>(L3, D) Как не сделать ложных выводов по flamegraph без дополнительных метрик?</p>\n","answer":"<p><strong>Ответ:</strong> Дополнить график elapsed time, throughput, counters и wait traces; профиль описывает только выбранный тип samples.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/brendangregg/FlameGraph\">FlameGraph</a></p>\n","group":"L3","line":653},{"id":"content/06_tools_build_debug/04_performance.md:f3c0a22bbeebb8f1:1","question":"<p>(L4, S) Как встроить flamegraphs в performance review pipeline?</p>\n","answer":"<p><strong>Ответ:</strong> Сохранять baseline/candidate profiles с метаданными и запускать review при воспроизводимом ухудшении KPI.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/brendangregg/FlameGraph\">FlameGraph</a></p>\n","group":"L4","line":662},{"id":"content/06_tools_build_debug/04_performance.md:ee1fd499ce916cc3:1","question":"<p>(L4, D) Как использовать flamegraphs для обучения команды performance thinking?</p>\n","answer":"<p><strong>Ответ:</strong> Разбирать реальные широкие пути и проверять гипотезы небольшим экспериментом; не приравнивать визуальную ширину к дефекту.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/brendangregg/FlameGraph\">FlameGraph</a></p>\n","group":"L4","line":668},{"id":"content/06_tools_build_debug/04_performance.md:01e40cfb60f4f660:1","question":"<p>(L4, S) Как автоматизировать генерацию flamegraphs для regression analysis?</p>\n","answer":"<p><strong>Ответ:</strong> Скриптовать запись, symbolization, folding и rendering; хранить raw data вместе с commit и workload.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/brendangregg/FlameGraph\">FlameGraph</a></p>\n","group":"L4","line":674},{"id":"content/06_tools_build_debug/04_performance.md:deacfbc1d1e04486:1","question":"<p>(L4, D) Когда flamegraph лучше таблицы hot functions, а когда хуже?</p>\n","answer":"<p><strong>Ответ:</strong> Он лучше показывает контекст и общие пути; таблица удобнее для точных чисел, сортировки и сравнения self cost.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/brendangregg/FlameGraph\">FlameGraph</a></p>\n","group":"L4","line":680},{"id":"content/06_tools_build_debug/04_performance.md:f823722ebb2c0f3f:1","question":"<p>(L4, S) Как объединять flamegraphs с counters и benchmark-результатами в единую картину?</p>\n","answer":"<p><strong>Ответ:</strong> Привязать один workload и build ID к времени, CPU samples и counters; вывод должен объяснять измеренное изменение KPI.</p>\n<pre><code> **Источник:** [FlameGraph](https://github.com/brendangregg/FlameGraph)\n</code></pre>\n<hr />\n","group":"L4","line":686},{"id":"content/06_tools_build_debug/04_performance.md:c44d0b5f3f6c5488:1","question":"<p>(L1, T) Что такое memory profiling?</p>\n","answer":"<p><strong>Ответ:</strong> Измерение выделений, живых объектов, пиков и поведения памяти во времени; RSS и heap bytes анализируют отдельно.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L1","line":699},{"id":"content/06_tools_build_debug/04_performance.md:66e6e60c2b25526e:1","question":"<p>(L1, T) Чем memory leak отличается от high memory usage?</p>\n","answer":"<p><strong>Ответ:</strong> Leak означает потерю нужного освобождения или бесконтрольное удержание; большой полезный working set сам по себе не утечка.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L1","line":705},{"id":"content/06_tools_build_debug/04_performance.md:6fd000d2e1fc21f2:1","question":"<p>(L1, T) Что такое heap profiling?</p>\n","answer":"<p><strong>Ответ:</strong> Сбор allocation/free событий или samples с attribution к стеку для анализа heap usage и churn.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L1","line":711},{"id":"content/06_tools_build_debug/04_performance.md:4dcb22ebfb66a1c3:1","question":"<p>(L1, T) Что такое stack memory vs heap memory?</p>\n","answer":"<p><strong>Ответ:</strong> Stack обычно хранит контекст вызовов и автоматические объекты; dynamic storage выделяется allocator. Размещение оптимизированных объектов может отличаться.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L1","line":717},{"id":"content/06_tools_build_debug/04_performance.md:afa19bfcd1aeae93:1","question":"<p>(L1, T) Почему большое число аллокаций может быть проблемой даже без leak?</p>\n","answer":"<p><strong>Ответ:</strong> Каждое выделение несёт overhead, metadata и иногда contention/page faults, даже если память потом освобождена.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L1","line":723},{"id":"content/06_tools_build_debug/04_performance.md:74bbd4e27f5c9ddb:1","question":"<p>(L1, T) Что такое fragmentation?</p>\n","answer":"<p><strong>Ответ:</strong> Неэффективное использование памяти из-за свободных промежутков, округлений размеров и удерживаемых частично занятых страниц.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L1","line":729},{"id":"content/06_tools_build_debug/04_performance.md:4790111c9f5fa455:1","question":"<p>(L1, T) Что такое cache locality?</p>\n","answer":"<p><strong>Ответ:</strong> Переиспользование близких по времени или адресу данных, позволяющее эффективно использовать cache lines.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L1","line":735},{"id":"content/06_tools_build_debug/04_performance.md:6dffba26e940f816:1","question":"<p>(L1, T) Почему locality влияет на производительность?</p>\n","answer":"<p><strong>Ответ:</strong> Cache hit обычно существенно дешевле доступа к дальней памяти; locality уменьшает ожидание и трафик памяти.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L1","line":741},{"id":"content/06_tools_build_debug/04_performance.md:7aafc6271960229d:1","question":"<p>(L1, P) Какие признаки memory problem можно заметить без профайлера?</p>\n","answer":"<p><strong>Ответ:</strong> Рост RSS, page faults, swap, OOM, allocator CPU и latency; это симптомы для дальнейшего измерения.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L1","line":747},{"id":"content/06_tools_build_debug/04_performance.md:d9f269b6b8e3a834:1","question":"<p>(L1, D) Почему рост RSS не всегда означает leak?</p>\n","answer":"<p><strong>Ответ:</strong> Allocator retention, caches, mappings и полезные данные могут увеличивать RSS без потерянных allocation.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L1","line":753},{"id":"content/06_tools_build_debug/04_performance.md:c88e69f82b3cf5ec:1","question":"<p>(L2, T) Что показывает heap profiler?</p>\n","answer":"<p><strong>Ответ:</strong> Текущие/пиковые объёмы, allocation counts и вызывающие стеки; конкретные метрики зависят от инструмента.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L2","line":762},{"id":"content/06_tools_build_debug/04_performance.md:52440c998a0c6a54:1","question":"<p>(L2, D) Как понять, какие участки кода чаще всего аллоцируют память?</p>\n","answer":"<p><strong>Ответ:</strong> Снять allocation profile и отсортировать по count и bytes; горячая по числу функция не обязательно крупнейшая по объёму.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L2","line":768},{"id":"content/06_tools_build_debug/04_performance.md:1f96c7a6962fd30b:1","question":"<p>(L2, D) Почему allocator может удерживать память после free?</p>\n","answer":"<p><strong>Ответ:</strong> Для повторного использования arenas и size classes; свободный блок не всегда позволяет освободить целую страницу ОС.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L2","line":774},{"id":"content/06_tools_build_debug/04_performance.md:aabc09318fb5e5c6:1","question":"<p>(L2, T) В чем разница virtual memory, RSS и working set?</p>\n","answer":"<p><strong>Ответ:</strong> Virtual memory — адресные mappings; RSS — резидентные страницы; working set — активно используемые данные на выбранном интервале.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L2","line":780},{"id":"content/06_tools_build_debug/04_performance.md:7142fd80a81c30f1:1","question":"<p>(L2, D) Как fragmentation ухудшает memory footprint?</p>\n","answer":"<p><strong>Ответ:</strong> Полезные байты занимают больше страниц из-за holes, alignment и округления size classes.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L2","line":786},{"id":"content/06_tools_build_debug/04_performance.md:c5373012071fcc2c:1","question":"<p>(L2, D) Как fragmentation влияет на latency?</p>\n","answer":"<p><strong>Ответ:</strong> Увеличивает footprint, cache/TLB pressure и вероятность page faults; эффект зависит от allocator и workload.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L2","line":792},{"id":"content/06_tools_build_debug/04_performance.md:d50d0f09bff44b49:1","question":"<p>(L2, T) Что такое temporal locality?</p>\n","answer":"<p><strong>Ответ:</strong> Повторное обращение к недавно использованным данным, пока они ещё находятся в cache.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L2","line":798},{"id":"content/06_tools_build_debug/04_performance.md:d2a1e91427c1ec1c:1","question":"<p>(L2, T) Что такое spatial locality?</p>\n","answer":"<p><strong>Ответ:</strong> Обращение к соседним адресам, загруженным одной cache line или предвыбранным аппаратурой.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L2","line":804},{"id":"content/06_tools_build_debug/04_performance.md:ac73e4f6229af9f5:1","question":"<p>(L2, D) Почему linked list часто хуже vector с точки зрения locality?</p>\n","answer":"<p><strong>Ответ:</strong> Узлы list часто разнесены и требуют зависимых pointer loads; vector обеспечивает последовательный компактный обход.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L2","line":810},{"id":"content/06_tools_build_debug/04_performance.md:e79645fa35fcdf37:1","question":"<p>(L2, P) Какие практические способы улучшить cache locality ты знаешь?</p>\n","answer":"<p><strong>Ответ:</strong> Плотные массивы, batching, hot/cold splitting, SoA для выборочных полей и порядок обхода по размещению данных.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L2","line":816},{"id":"content/06_tools_build_debug/04_performance.md:0ce75dcfaafae96b:1","question":"<p>(L3, T) Как heap profiler собирает данные об аллокациях?</p>\n","answer":"<p><strong>Ответ:</strong> Через allocator hooks/interposition, встроенные профили или sampling; стеки и объём событий создают overhead.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L3","line":825},{"id":"content/06_tools_build_debug/04_performance.md:cd30d6980c14a026:1","question":"<p>(L3, D) Как различить leak, churn и allocator retention?</p>\n","answer":"<p><strong>Ответ:</strong> Сравнить live bytes, allocation rate и RSS после спада нагрузки; retention требует статистики allocator, leak — анализа владельцев.</p>\n<p><strong>Пример:</strong> После одинаковых циклов нагрузки:</p>\n<p>| Наблюдение | Проверяемая гипотеза |\n| --- | --- |\n| Live bytes растут и не возвращаются | Leak, неограниченный cache или очередь |\n| Allocation count велик, live bytes стабильны | Churn |\n| Live bytes падают, RSS остаётся | Retention/fragmentation либо другие mappings |</p>\n<p><strong>Типичная ошибка:</strong> Делать вывод об утечке только по RSS.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L3","line":831},{"id":"content/06_tools_build_debug/04_performance.md:1c16ddf646989f86:1","question":"<p>(L3, D) Почему большое число мелких аллокаций опасно для производительности?</p>\n","answer":"<p><strong>Ответ:</strong> Растут metadata, calls, fragmentation и lock/cache pressure; проверять стоимость на операцию.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L3","line":847},{"id":"content/06_tools_build_debug/04_performance.md:7e777856c5375d24:1","question":"<p>(L3, D) Как profiling помогает найти ненужные копирования и временные объекты?</p>\n","answer":"<p><strong>Ответ:</strong> Профиль показывает allocation stacks временных строк/контейнеров; CPU profile и inspection подтверждают копирующие пути.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L3","line":853},{"id":"content/06_tools_build_debug/04_performance.md:02de1a7523257b49:1","question":"<p>(L3, D) Как понять, что bottleneck связан с allocator contention?</p>\n","answer":"<p><strong>Ответ:</strong> Проверить wait stacks и CPU в allocator locks, затем сравнить шардирование или иной allocator при том же workload.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L3","line":859},{"id":"content/06_tools_build_debug/04_performance.md:ce03a85db0cc08d1:1","question":"<p>(L3, T) Что такое NUMA и почему это важно для memory profiling?</p>\n","answer":"<p><strong>Ответ:</strong> Память NUMA-узлов имеет разную стоимость доступа для CPU; важны placement, first touch и миграции потоков.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L3","line":865},{"id":"content/06_tools_build_debug/04_performance.md:93725e5c4db335b9:1","question":"<p>(L3, D) Как плохая locality проявляется в CPU profile?</p>\n","answer":"<p><strong>Ответ:</strong> Видны дорогие load-heavy пути и низкий IPC; нужны cache/TLB и memory latency events для подтверждения.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L3","line":871},{"id":"content/06_tools_build_debug/04_performance.md:c1c72e10bda7e340:1","question":"<p>(L3, D) Как layout данных влияет на cache misses?</p>\n","answer":"<p><strong>Ответ:</strong> Размер, порядок и группировка полей определяют число затронутых линий и полезных байтов на загрузку.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L3","line":877},{"id":"content/06_tools_build_debug/04_performance.md:6f149ed4390f13b5:1","question":"<p>(L3, D) Почему AoS vs SoA может радикально менять производительность?</p>\n","answer":"<p><strong>Ответ:</strong> SoA удобнее при проходе по отдельным полям и SIMD; AoS может быть лучше при использовании всех полей объекта.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L3","line":883},{"id":"content/06_tools_build_debug/04_performance.md:3da9f54eca91ff90:1","question":"<p>(L3, P) Как профилировать memory-heavy код в long-running service?</p>\n","answer":"<p><strong>Ответ:</strong> Использовать ограниченный sampling, snapshots и allocator metrics на репрезентативных фазах; измерить overhead и сохранить workload context.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L3","line":889},{"id":"content/06_tools_build_debug/04_performance.md:dac06d706e6173a2:1","question":"<p>(L4, S) Как проектировать data structures с учетом locality?</p>\n","answer":"<p><strong>Ответ:</strong> Начать с паттернов доступа и размера working set, затем выбрать компактный layout и проверить benchmark на реальных размерах.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L4","line":898},{"id":"content/06_tools_build_debug/04_performance.md:8a2fdf9253021990:1","question":"<p>(L4, S) Когда стоит внедрять custom allocator/pool allocator?</p>\n","answer":"<p><strong>Ответ:</strong> Когда измерены allocator overhead/fragmentation и понятны lifetime/size patterns; учитывать сложность освобождения и retained capacity.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L4","line":904},{"id":"content/06_tools_build_debug/04_performance.md:d179b8f3285cc43a:1","question":"<p>(L4, D) Как расследовать memory bloat в production без полного доступа к процессу?</p>\n","answer":"<p><strong>Ответ:</strong> Собирать RSS/PSS, mappings, allocator stats и workload; сравнить рост live data с кешами и очередями.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L4","line":910},{"id":"content/06_tools_build_debug/04_performance.md:713cd6e0fe615f92:1","question":"<p>(L4, S) Как встроить memory profiling в CI/performance lab?</p>\n","answer":"<p><strong>Ответ:</strong> Выделить сценарии steady-state и peak, фиксировать live/peak bytes и allocation rate; пороги проверять повторными запусками.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L4","line":916},{"id":"content/06_tools_build_debug/04_performance.md:5ed429002b736ea9:1","question":"<p>(L4, S) Как отличать архитектурную memory problem от локального implementation bug?</p>\n","answer":"<p><strong>Ответ:</strong> Если растут обязательные копии, queues и caches — искать архитектуру; если утрачено освобождение конкретного объекта — ownership bug.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L4","line":922},{"id":"content/06_tools_build_debug/04_performance.md:c77fb038e694514c:1","question":"<p>(L1, T) Что такое heap snapshot?</p>\n","answer":"<p><strong>Ответ:</strong> Снимок heap на выбранном этапе с размерами и attribution; данные о владельцах зависят от профилировщика.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L1","line":933},{"id":"content/06_tools_build_debug/04_performance.md:0c70b9097140bea2:1","question":"<p>(L1, T) Что означает allocation hotspot?</p>\n","answer":"<p><strong>Ответ:</strong> Участок с большим allocation count или bytes; нужно явно выбрать метрику и интервал.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L1","line":939},{"id":"content/06_tools_build_debug/04_performance.md:11144da7204ef4eb:1","question":"<p>(L1, P) Что полезно смотреть в heap profile в первую очередь?</p>\n","answer":"<p><strong>Ответ:</strong> Peak/live bytes, крупнейшие allocation stacks, count и динамику после нагрузки; затем retained memory allocator.</p>\n<p><strong>Пример:</strong> Для отдельного лабораторного запуска:</p>\n<pre><code class=\"language-bash\">valgrind --tool=massif --massif-out-file=massif.out ./app input.dat\nms_print massif.out\n</code></pre>\n<p>Massif меняет скорость исполнения; timing этого запуска не используют как production latency.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L1","line":945},{"id":"content/06_tools_build_debug/04_performance.md:69488672a5e1794f:1","question":"<p>(L1, D) Почему один и тот же код может давать разные heap profile на разных входных данных?</p>\n","answer":"<p><strong>Ответ:</strong> Размеры и распределение входа меняют capacity, branches, caching и частоту временных объектов.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L1","line":960},{"id":"content/06_tools_build_debug/04_performance.md:8721e6a277ad0299:1","question":"<p>(L1, T) Почему количество аллокаций и объем аллокаций — разные метрики?</p>\n","answer":"<p><strong>Ответ:</strong> Миллион мелких allocation и одна крупная имеют разную CPU-стоимость при одинаковом суммарном объёме.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L1","line":966},{"id":"content/06_tools_build_debug/04_performance.md:3123988da115887b:1","question":"<p>(L2, D) Как выявить функцию, которая делает лишние аллокации?</p>\n","answer":"<p><strong>Ответ:</strong> Сравнить allocation stacks/count на одну операцию и проверить ненужные temporaries, conversions и growth.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L2","line":975},{"id":"content/06_tools_build_debug/04_performance.md:6e4c031e198da10c:1","question":"<p>(L2, D) Почему <code>std::string</code>/<code>std::vector</code> могут неожиданно аллоцировать часто?</p>\n","answer":"<p><strong>Ответ:</strong> Рост capacity, копирование и создание временных значений могут выделять память; SSO не гарантируется для всех строк.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L2","line":981},{"id":"content/06_tools_build_debug/04_performance.md:540b63829d320598:1","question":"<p>(L2, P) Как проверить гипотезу, что reserve/reuse уменьшит churn?</p>\n","answer":"<p><strong>Ответ:</strong> Снять count/bytes и latency до/после <code>reserve()</code> или reuse на одинаковой нагрузке; учесть увеличенный retained capacity.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L2","line":987},{"id":"content/06_tools_build_debug/04_performance.md:5670f28e8aebaa59:1","question":"<p>(L2, D) Как heap profiling помогает в оптимизации latency-sensitive кода?</p>\n","answer":"<p><strong>Ответ:</strong> Позволяет убрать непредсказуемые allocation/reallocation из критического пути и измерить изменение хвостов latency.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L2","line":993},{"id":"content/06_tools_build_debug/04_performance.md:b9ecba8310bb513f:1","question":"<p>(L2, T) Почему allocator behavior зависит от паттернов освобождения памяти?</p>\n","answer":"<p><strong>Ответ:</strong> Size classes, порядок освобождения и lifetime определяют доступность reusable blocks и полностью свободных страниц.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L2","line":999},{"id":"content/06_tools_build_debug/04_performance.md:1e94756b356bda66:1","question":"<p>(L3, D) Как находить allocation hot path через combined CPU + memory profile?</p>\n","answer":"<p><strong>Ответ:</strong> Связать горячие allocator callers в CPU profile с count/bytes в heap profile на одном сценарии.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L3","line":1008},{"id":"content/06_tools_build_debug/04_performance.md:d3953d2a76a0bddf:1","question":"<p>(L3, D) Как отличить полезные аллокации от accidental allocations?</p>\n","answer":"<p><strong>Ответ:</strong> Полезные обеспечивают контракт и хранение результата; accidental возникают из лишних копий/преобразований и удаляются без смены семантики.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L3","line":1014},{"id":"content/06_tools_build_debug/04_performance.md:b847693719a1bbb1:1","question":"<p>(L3, S) Какие аллокации допустимы в hot path, а какие нет?</p>\n","answer":"<p><strong>Ответ:</strong> Допустимость задаёт latency budget и измерения; bounded заранее выделенная память часто предпочтительнее непредсказуемой аллокации.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L3","line":1020},{"id":"content/06_tools_build_debug/04_performance.md:656463d68ec853ec:1","question":"<p>(L3, D) Как профилировать аллокации в многопоточной программе?</p>\n","answer":"<p><strong>Ответ:</strong> Нужен thread-aware profiler и корректные stacks; сравнивать local/cross-thread free и shared allocator contention.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L3","line":1026},{"id":"content/06_tools_build_debug/04_performance.md:9a46a87de27a72a9:1","question":"<p>(L3, D) Почему heap profile без контекста workload может ввести в заблуждение?</p>\n","answer":"<p><strong>Ответ:</strong> Одинаковый footprint может быть нормой для большого входа и регрессией для малого; нужны units per request и фаза работы.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L3","line":1032},{"id":"content/06_tools_build_debug/04_performance.md:2a0cd4071f72280d:1","question":"<p>(L1, T) Что такое external fragmentation?</p>\n","answer":"<p><strong>Ответ:</strong> Свободные блоки распределены так, что не подходят требуемому размещению или возврату страниц.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L1","line":1043},{"id":"content/06_tools_build_debug/04_performance.md:f984832fa75f2a49:1","question":"<p>(L1, T) Что такое internal fragmentation?</p>\n","answer":"<p><strong>Ответ:</strong> Выделенный блок больше полезного объекта из-за alignment, size-class rounding и metadata.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L1","line":1049},{"id":"content/06_tools_build_debug/04_performance.md:feca202a1572fc7e:1","question":"<p>(L1, D) Почему fragmentation может приводить к росту памяти без leak?</p>\n","answer":"<p><strong>Ответ:</strong> Небольшое число живых объектов может удерживать множество страниц с неиспользуемыми промежутками.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L1","line":1055},{"id":"content/06_tools_build_debug/04_performance.md:a2ca484df00d5e56:1","question":"<p>(L1, T) Как размеры объектов влияют на fragmentation?</p>\n","answer":"<p><strong>Ответ:</strong> Разнообразие размеров и округления влияют на waste; одинаковые размеры часто проще переиспользовать в size classes.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L1","line":1061},{"id":"content/06_tools_build_debug/04_performance.md:86a06529d6d23571:1","question":"<p>(L1, D) Почему долгоживущие и короткоживущие объекты вместе — риск для fragmentation?</p>\n","answer":"<p><strong>Ответ:</strong> Живые объекты мешают освободить страницы, на которых уже удалены короткоживущие соседи.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L1","line":1067},{"id":"content/06_tools_build_debug/04_performance.md:b171659735b416ba:1","question":"<p>(L2, D) Как заподозрить fragmentation по симптомам?</p>\n","answer":"<p><strong>Ответ:</strong> RSS остаётся большим при малом live heap; подтвердить allocator stats, исключив mappings и caches.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L2","line":1076},{"id":"content/06_tools_build_debug/04_performance.md:46183dafe5817c6a:1","question":"<p>(L2, D) Почему fragmentation опасна для сервисов с длительным uptime?</p>\n","answer":"<p><strong>Ответ:</strong> Разнообразные циклы нагрузки постепенно меняют распределение свободных блоков и удерживаемых страниц.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L2","line":1082},{"id":"content/06_tools_build_debug/04_performance.md:fbab39d3bb6b8a43:1","question":"<p>(L2, T) Как allocator design влияет на fragmentation?</p>\n","answer":"<p><strong>Ответ:</strong> Size classes, arenas, coalescing и release policy определяют баланс reuse, contention и footprint.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L2","line":1088},{"id":"content/06_tools_build_debug/04_performance.md:907139f95a26d6f1:1","question":"<p>(L2, D) Как object pooling может помочь?</p>\n","answer":"<p><strong>Ответ:</strong> Объединяет одинаковые объекты и переиспользует storage; требует лимита и ясного lifetime.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L2","line":1094},{"id":"content/06_tools_build_debug/04_performance.md:d1b1d0633e8097c4:1","question":"<p>(L2, D) Когда pooling ухудшает ситуацию?</p>\n","answer":"<p><strong>Ответ:</strong> При завышенной capacity, неоднородных объектах, удержании peak memory и shared pool contention.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L2","line":1100},{"id":"content/06_tools_build_debug/04_performance.md:47c58742b9925cec:1","question":"<p>(L3, D) Как отличить fragmentation от allocator caching?</p>\n","answer":"<p><strong>Ответ:</strong> Сравнить полезные, active и resident bytes средствами allocator; свободные целые страницы отличаются от дыр в занятых.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L3","line":1109},{"id":"content/06_tools_build_debug/04_performance.md:9ed9203cd797055b:1","question":"<p>(L3, D) Как fragmentation влияет на page faults и locality?</p>\n","answer":"<p><strong>Ответ:</strong> Разбрасывание живых объектов увеличивает число страниц/cache lines; faults зависят от резидентности, а не fragmentation автоматически.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L3","line":1115},{"id":"content/06_tools_build_debug/04_performance.md:02e384db7d5b8240:1","question":"<p>(L3, S) Какие архитектурные решения уменьшают fragmentation?</p>\n","answer":"<p><strong>Ответ:</strong> Разделение объектов по lifetime/size, bounded pools, компактные структуры и ограниченные caches.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L3","line":1121},{"id":"content/06_tools_build_debug/04_performance.md:3f69c5e651f52231:1","question":"<p>(L3, D) Как mixed-size allocations влияют на long-term footprint?</p>\n","answer":"<p><strong>Ответ:</strong> Чередование размеров и сроков жизни оставляет трудно переиспользуемые промежутки; эффект зависит от allocator.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L3","line":1127},{"id":"content/06_tools_build_debug/04_performance.md:8a8c3f239e023bb3:1","question":"<p>(L3, D) Как profiling подтвердит, что проблема именно во fragmentation?</p>\n","answer":"<p><strong>Ответ:</strong> Нужны allocator occupancy/fragmentation stats и live heap; один RSS-график не отличает fragmentation от retention.</p>\n<p><strong>Источник:</strong> <a href=\"https://valgrind.org/docs/manual/ms-manual.html\">Valgrind: Massif</a>; <a href=\"https://man7.org/linux/man-pages/man5/proc.5.html\">Linux: proc(5)</a></p>\n","group":"L3","line":1133},{"id":"content/06_tools_build_debug/04_performance.md:61834a831a593dad:1","question":"<p>(L1, T) Что такое CPU cache?</p>\n","answer":"<p><strong>Ответ:</strong> Небольшая быстрая память рядом с CPU, сохраняющая копии данных и инструкций из более медленных уровней.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L1","line":1144},{"id":"content/06_tools_build_debug/04_performance.md:0eab0ea315bab72c:1","question":"<p>(L1, T) Какие уровни кэша обычно есть?</p>\n","answer":"<p><strong>Ответ:</strong> Обычно L1, L2 и L3/LLC; размеры, sharing и inclusive policy зависят от процессора.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L1","line":1150},{"id":"content/06_tools_build_debug/04_performance.md:54386a87cfdae063:1","question":"<p>(L1, T) Что такое cache line?</p>\n","answer":"<p><strong>Ответ:</strong> Единица переноса и coherence cache, часто 64 байта, но размер платформенно зависим.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L1","line":1156},{"id":"content/06_tools_build_debug/04_performance.md:304c4a3a2658835b:1","question":"<p>(L1, T) Почему последовательный доступ обычно быстрее случайного?</p>\n","answer":"<p><strong>Ответ:</strong> Использует соседние байты линии и prefetch; случайный доступ чаще ждёт независимые cache/TLB misses.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L1","line":1162},{"id":"content/06_tools_build_debug/04_performance.md:69336b8bd93f3dc3:1","question":"<p>(L1, D) Почему pointer chasing часто медленный?</p>\n","answer":"<p><strong>Ответ:</strong> Адрес следующего узла зависит от предыдущей загрузки, ограничивая prefetch и memory-level parallelism.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L1","line":1168},{"id":"content/06_tools_build_debug/04_performance.md:459f4cf28d9f4482:1","question":"<p>(L2, D) Как locality влияет на throughput?</p>\n","answer":"<p><strong>Ответ:</strong> Меньше memory stalls позволяет выполнить больше операций за время при том же CPU budget.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":1177},{"id":"content/06_tools_build_debug/04_performance.md:4fabd9428824823c:1","question":"<p>(L2, D) Как locality влияет на latency?</p>\n","answer":"<p><strong>Ответ:</strong> Меньше cache/TLB misses сокращает обслуживание запроса; хвосты дополнительно зависят от очередей и scheduling.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":1183},{"id":"content/06_tools_build_debug/04_performance.md:6af02b6003591ae4:1","question":"<p>(L2, P) Какие структуры данных обычно лучше с точки зрения locality?</p>\n","answer":"<p><strong>Ответ:</strong> Компактные arrays/vector, flat containers и структуры с плотным hot data; выбор проверяют на реальном доступе.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":1189},{"id":"content/06_tools_build_debug/04_performance.md:44066949d8e3671d:1","question":"<p>(L2, D) Почему <code>std::vector</code> часто быстрее <code>std::list</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Последовательное размещение уменьшает pointer chasing и overhead узлов; преимущества list зависят от операций.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":1195},{"id":"content/06_tools_build_debug/04_performance.md:be9b9e45bface722:1","question":"<p>(L2, D) Как data layout влияет на performance больше, чем микрооптимизации кода?</p>\n","answer":"<p><strong>Ответ:</strong> Layout меняет объём memory traffic и stalls, которые могут доминировать над стоимостью отдельных инструкций.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":1201},{"id":"content/06_tools_build_debug/04_performance.md:2d030aae934a846a:1","question":"<p>(L3, T) Что такое cache-friendly algorithm?</p>\n","answer":"<p><strong>Ответ:</strong> Алгоритм, организующий доступ так, чтобы переиспользовать cache-resident данные: например blocked matrix traversal.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":1210},{"id":"content/06_tools_build_debug/04_performance.md:02da53a7c8b56962:1","question":"<p>(L3, D) Как профилировать cache misses?</p>\n","answer":"<p><strong>Ответ:</strong> Начать с <code>perf stat -e cache-references,cache-misses -- ./app</code>, затем использовать события конкретной PMU и профиль.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":1216},{"id":"content/06_tools_build_debug/04_performance.md:51c057973909ff07:1","question":"<p>(L3, D) Как false locality assumptions приводят к неправильным выводам?</p>\n","answer":"<p><strong>Ответ:</strong> Малый тест может полностью помещаться в cache, хотя production working set значительно больше; нужны разные размеры.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":1222},{"id":"content/06_tools_build_debug/04_performance.md:707cdc141c15a771:1","question":"<p>(L3, D) Как branchy code и poor locality взаимно усиливают slowdown?</p>\n","answer":"<p><strong>Ответ:</strong> Непредсказуемые ветви нарушают pipeline, а зависимые misses мешают скрывать latency; степень эффекта измеряют.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":1228},{"id":"content/06_tools_build_debug/04_performance.md:4026563d4470441f:1","question":"<p>(L3, S) Когда нужно redesign data layout ради locality?</p>\n","answer":"<p><strong>Ответ:</strong> Когда подтверждён memory bottleneck и локальные изменения не обеспечивают цель; учитывать API, memory cost и сопровождение.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":1234},{"id":"content/06_tools_build_debug/04_performance.md:f1de52e9f20c040c:1","question":"<p>(L4, S) Как обучать команду думать категориями data-oriented performance?</p>\n","answer":"<p><strong>Ответ:</strong> Обсуждать рабочие наборы, access patterns и ownership на примерах с измерениями, а не вводить универсальный запрет abstractions.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L4","line":1243},{"id":"content/06_tools_build_debug/04_performance.md:f49012a719033f91:1","question":"<p>(L4, D) Как доказать, что bottleneck именно в locality, а не в “медленном CPU”?</p>\n","answer":"<p><strong>Ответ:</strong> Сохранить CPU и workload, изменить только layout/access pattern и подтвердить снижение misses и времени.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L4","line":1249},{"id":"content/06_tools_build_debug/04_performance.md:e0a51e3e809bd6c2:1","question":"<p>(L4, S) Как встроить locality review в code review/perf review процесс?</p>\n","answer":"<p><strong>Ответ:</strong> Для горячих структур проверять размер, stride, hot fields и concurrency; требовать измерения только для значимых путей.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L4","line":1255},{"id":"content/06_tools_build_debug/04_performance.md:dfbb03bd46e71be6:1","question":"<p>(L4, D) Как локально воспроизвести production locality problem?</p>\n","answer":"<p><strong>Ответ:</strong> Воспроизвести cardinality, skew, object sizes, NUMA placement и concurrency, а не только число запросов.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L4","line":1261},{"id":"content/06_tools_build_debug/04_performance.md:9119f7ef4704d29f:1","question":"<p>(L4, S) Как принимать trade-off между readability/abstraction и locality?</p>\n","answer":"<p><strong>Ответ:</strong> Выделять специализированный hot path с понятным интерфейсом; принимать усложнение только при воспроизводимом полезном эффекте.</p>\n<pre><code> **Источник:** [perf tools documentation](https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation)\n</code></pre>\n<hr />\n","group":"L4","line":1267},{"id":"content/06_tools_build_debug/04_performance.md:85bb0b9559fcc3d8:1","question":"<p>(L1, T) Что такое benchmark?</p>\n","answer":"<p><strong>Ответ:</strong> Контролируемое выполнение заданной нагрузки с измерением выбранных показателей и зафиксированным окружением.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L1","line":1280},{"id":"content/06_tools_build_debug/04_performance.md:61b1ebd8bfaa316a:1","question":"<p>(L1, T) Чем microbenchmark отличается от macrobenchmark?</p>\n","answer":"<p><strong>Ответ:</strong> Microbenchmark измеряет узкий компонент; macrobenchmark — взаимодействие подсистем на более полном сценарии.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L1","line":1286},{"id":"content/06_tools_build_debug/04_performance.md:ee9532f4f4f4616c:1","question":"<p>(L1, T) Когда microbenchmark полезен?</p>\n","answer":"<p><strong>Ответ:</strong> Для сравнения реализаций конкретной операции при реалистичных размерах и исключённых измерительных артефактах.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L1","line":1292},{"id":"content/06_tools_build_debug/04_performance.md:ffd6164f1ab09edb:1","question":"<p>(L1, T) Когда microbenchmark вводит в заблуждение?</p>\n","answer":"<p><strong>Ответ:</strong> При неверном working set, оптимизированном прочь коде, отсутствии contention или нерепрезентативном входе.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L1","line":1298},{"id":"content/06_tools_build_debug/04_performance.md:6bd79ac92aa17fb9:1","question":"<p>(L1, T) Что важно фиксировать при измерении benchmark?</p>\n","answer":"<p><strong>Ответ:</strong> Commit, flags/toolchain, CPU/kernel, workload, warm-up, единицы метрики и число повторов.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L1","line":1304},{"id":"content/06_tools_build_debug/04_performance.md:5d616601c4d6f6d2:1","question":"<p>(L1, P) Почему нужно делать несколько прогонов?</p>\n","answer":"<p><strong>Ответ:</strong> Чтобы оценить вариативность и отличить устойчивое изменение от шума окружения.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L1","line":1310},{"id":"content/06_tools_build_debug/04_performance.md:eea91713375adaff:1","question":"<p>(L1, T) Что такое warm-up?</p>\n","answer":"<p><strong>Ответ:</strong> Фаза стабилизации caches, allocations и состояния приложения; cold-start измеряют отдельно, если он важен.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L1","line":1316},{"id":"content/06_tools_build_debug/04_performance.md:13e89fdc9d91c25b:1","question":"<p>(L1, D) Почему “один запуск” нельзя считать доказательством?</p>\n","answer":"<p><strong>Ответ:</strong> Единичный результат смешивает эффект кода с scheduling, frequency и случайным состоянием памяти.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L1","line":1322},{"id":"content/06_tools_build_debug/04_performance.md:0927a6704c175961:1","question":"<p>(L1, T) Что такое variance в измерениях?</p>\n","answer":"<p><strong>Ответ:</strong> Разброс результатов относительно среднего; распределение и выбросы важны для доверия к сравнению.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L1","line":1328},{"id":"content/06_tools_build_debug/04_performance.md:b03b2c01683efd70:1","question":"<p>(L1, D) Почему benchmark на ноутбуке может быть нестабилен?</p>\n","answer":"<p><strong>Ответ:</strong> Меняются питание, turbo, температура, фоновые процессы и размещение потоков.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L1","line":1334},{"id":"content/06_tools_build_debug/04_performance.md:c0ed4853dc347a9f:1","question":"<p>(L2, T) Как оптимизации компилятора влияют на benchmark?</p>\n","answer":"<p><strong>Ответ:</strong> Inlining, vectorization и устранение кода меняют измеряемую работу; benchmark должен использовать production-like flags.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L2","line":1343},{"id":"content/06_tools_build_debug/04_performance.md:50e44d2f5dc90de8:1","question":"<p>(L2, D) Почему компилятор может “выкинуть” код из microbenchmark?</p>\n","answer":"<p><strong>Ответ:</strong> Если вычисление не имеет наблюдаемого результата, as-if rule позволяет удалить его полностью.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L2","line":1349},{"id":"content/06_tools_build_debug/04_performance.md:6a62a9c7c7b4bf83:1","question":"<p>(L2, P) Как предотвратить dead-code elimination в benchmark?</p>\n","answer":"<p><strong>Ответ:</strong> Использовать <code>benchmark::DoNotOptimize()</code> и при необходимости <code>ClobberMemory()</code>, затем проверить asm; volatile не универсальное решение.</p>\n<p><strong>Пример:</strong> Фрагмент для Google Benchmark; вход готовится вне измеряемого цикла.</p>\n<pre><code class=\"language-cpp\">#include &lt;benchmark/benchmark.h&gt;\n#include &lt;numeric&gt;\n#include &lt;vector&gt;\n\nstatic void BM_Sum(benchmark::State&amp; state) {\n    std::vector&lt;int&gt; values(4096, 1);\n    for (auto _ : state) {\n        benchmark::DoNotOptimize(values.data());\n        auto sum = std::accumulate(values.begin(), values.end(), 0LL);\n        benchmark::DoNotOptimize(sum);\n    }\n}\nBENCHMARK(BM_Sum);\nBENCHMARK_MAIN();\n</code></pre>\n<p>Это warm-cache microbenchmark суммирования, а не модель всей системы. Даже с barriers необходимо проверить generated code.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L2","line":1355},{"id":"content/06_tools_build_debug/04_performance.md:633c71139ab7a077:1","question":"<p>(L2, T) Почему <code>-O0</code> почти бесполезен для performance benchmark?</p>\n","answer":"<p><strong>Ответ:</strong> Он меняет layout, inlining и instruction count относительно production; полезен для отладки, но редко предсказывает release performance.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L2","line":1382},{"id":"content/06_tools_build_debug/04_performance.md:de7c81c054f1b68b:1","question":"<p>(L2, D) Почему benchmark должен соответствовать реальному workload?</p>\n","answer":"<p><strong>Ответ:</strong> Иначе оптимизируется другая пропорция операций, размеров и ожиданий, чем у пользователей.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L2","line":1388},{"id":"content/06_tools_build_debug/04_performance.md:0cb1897a2d789b9f:1","question":"<p>(L2, T) Что важнее: latency, throughput или tail latency?</p>\n","answer":"<p><strong>Ответ:</strong> Зависит от SLO: интерактивному сервису важны хвосты, batch — throughput; следить за стоимостью и всеми ограничениями.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L2","line":1394},{"id":"content/06_tools_build_debug/04_performance.md:9dd2180c6ab3a96d:1","question":"<p>(L2, P) Какие факторы окружения нужно стабилизировать перед benchmark?</p>\n","answer":"<p><strong>Ответ:</strong> CPU placement, governor/thermal state, фон, NUMA, вход, caches и версии окружения; фиксировать неизбежные различия.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L2","line":1400},{"id":"content/06_tools_build_debug/04_performance.md:898e32ff74a1db8f:1","question":"<p>(L2, D) Как CPU frequency scaling ломает чистоту измерений?</p>\n","answer":"<p><strong>Ответ:</strong> Разная частота меняет elapsed time при том же коде; фиксировать режим питания и наблюдать throttling.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L2","line":1406},{"id":"content/06_tools_build_debug/04_performance.md:b5d9bb67e67e0651:1","question":"<p>(L2, D) Как IO и page cache могут испортить benchmark?</p>\n","answer":"<p><strong>Ответ:</strong> Warm page cache скрывает disk I/O, а конкурирующий I/O добавляет noise; явно определить cold/warm сценарий.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L2","line":1412},{"id":"content/06_tools_build_debug/04_performance.md:fbb14e1d41d29c05:1","question":"<p>(L2, P) Чем полезны percentile-метрики вместо одного среднего значения?</p>\n","answer":"<p><strong>Ответ:</strong> p95/p99 показывают хвосты, скрытые средним; нужны достаточная выборка и корректная методика нагрузки.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L2","line":1418},{"id":"content/06_tools_build_debug/04_performance.md:ddceb3d678086ed7:1","question":"<p>(L3, T) Как проектировать representative macrobenchmark?</p>\n","answer":"<p><strong>Ответ:</strong> Воспроизвести operation mix, размеры, concurrency, arrival pattern и SLO; сохранять seed и проверять correctness результата.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L3","line":1427},{"id":"content/06_tools_build_debug/04_performance.md:85b934a29b66e789:1","question":"<p>(L3, D) Почему ускорение microbenchmark не гарантирует ускорение системы?</p>\n","answer":"<p><strong>Ответ:</strong> Компонент может занимать малую долю общего времени; bottleneck смещается или меняются взаимодействия.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L3","line":1433},{"id":"content/06_tools_build_debug/04_performance.md:927a49d9138aa4cf:1","question":"<p>(L3, D) Как benchmark может поощрять “оптимизацию не того”?</p>\n","answer":"<p><strong>Ответ:</strong> Слишком узкий KPI поощряет улучшение synthetic path за счёт памяти, хвостов или реального workload.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L3","line":1439},{"id":"content/06_tools_build_debug/04_performance.md:cce2064146a42012:1","question":"<p>(L3, T) Что такое benchmark harness?</p>\n","answer":"<p><strong>Ответ:</strong> Обвязка запуска, прогрева, повторов и сбора результатов; сама обвязка не должна доминировать в измерении.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L3","line":1445},{"id":"content/06_tools_build_debug/04_performance.md:c8d6102bea5c0578:1","question":"<p>(L3, P) Как сравнивать две версии алгоритма корректно?</p>\n","answer":"<p><strong>Ответ:</strong> Одинаковые inputs и flags, чередование A/B, независимые повторы, проверка результата и интервалы неопределённости.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L3","line":1451},{"id":"content/06_tools_build_debug/04_performance.md:a5ebc74a37d53903:1","question":"<p>(L3, D) Как отличить signal от noise в benchmark results?</p>\n","answer":"<p><strong>Ответ:</strong> Оценить baseline variance и повторяемость эффекта; случайный порядок запусков снижает влияние дрейфа машины.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L3","line":1457},{"id":"content/06_tools_build_debug/04_performance.md:34e68fe050a13067:1","question":"<p>(L3, D) Как понять, что разница 3% реальна, а не статистический шум?</p>\n","answer":"<p><strong>Ответ:</strong> Нужны достаточные независимые повторы и интервал оценки разницы уже 3%; одного среднего недостаточно.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L3","line":1463},{"id":"content/06_tools_build_debug/04_performance.md:a68066ff827588b0:1","question":"<p>(L3, T) Как работать с regression benchmark suite?</p>\n","answer":"<p><strong>Ответ:</strong> Хранить representative cases и baseline, отслеживать тренды, периодически убирать нерепрезентативные или нестабильные тесты.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L3","line":1469},{"id":"content/06_tools_build_debug/04_performance.md:e254076acd21afce:1","question":"<p>(L3, S) Как автоматизировать performance regression testing?</p>\n","answer":"<p><strong>Ответ:</strong> Выделенный runner, сохранение metadata/raw results, пороги относительно noise и повторная проверка перед блокировкой изменения.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L3","line":1475},{"id":"content/06_tools_build_debug/04_performance.md:d2581f75b9dee332:1","question":"<p>(L3, D) Как связывать benchmark-результаты с профилировщиком, а не гадать по цифрам?</p>\n","answer":"<p><strong>Ответ:</strong> Профилировать тот же scenario/build и проверить, что исчезла ожидаемая работа, а не поменялось окружение.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L3","line":1481},{"id":"content/06_tools_build_debug/04_performance.md:ae9998431399c1af:1","question":"<p>(L4, S) Как строить benchmarking culture в C/C++ команде?</p>\n","answer":"<p><strong>Ответ:</strong> Требовать гипотезу, baseline, воспроизводимый эксперимент и review эффекта; сохранять удачные и отвергнутые результаты.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L4","line":1490},{"id":"content/06_tools_build_debug/04_performance.md:c8318a5c4d01c68f:1","question":"<p>(L4, S) Как выбрать KPI для performance regression gates?</p>\n","answer":"<p><strong>Ответ:</strong> Выбирать пользовательские SLO и cost per operation; counters применять как диагностику, а не универсальный gate.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L4","line":1496},{"id":"content/06_tools_build_debug/04_performance.md:2452fa863b2f69fd:1","question":"<p>(L4, D) Как расследовать “benchmark improved, production worsened”?</p>\n","answer":"<p><strong>Ответ:</strong> Сравнить workload, tail latency, contention, memory footprint и compiler flags; проверить, не изменён ли алгоритмический контракт.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L4","line":1502},{"id":"content/06_tools_build_debug/04_performance.md:8ee51e7caec772f3:1","question":"<p>(L4, S) Как проектировать lab environment для достоверных benchmark'ов?</p>\n","answer":"<p><strong>Ответ:</strong> Контролировать железо, thermal state, CPU/NUMA placement, фон и software image; хранить калибровочные baseline runs.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L4","line":1508},{"id":"content/06_tools_build_debug/04_performance.md:ab9a60199312a741:1","question":"<p>(L4, S) Как совмещать synthetic benchmarks и production traces?</p>\n","answer":"<p><strong>Ответ:</strong> Traces задают распределения synthetic нагрузки; synthetic cases изолируют гипотезы, replay проверяет реалистичность эффекта.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a></p>\n","group":"L4","line":1514},{"id":"content/06_tools_build_debug/04_performance.md:eed846b6bf25d588:1","question":"<p>(L1, T) Почему один и тот же код на <code>-O0</code> и <code>-O3</code> ведет себя по-разному по скорости?</p>\n","answer":"<p><strong>Ответ:</strong> Оптимизации устраняют лишнюю работу, меняют inlining, register allocation и SIMD; UB может менять и поведение программы.</p>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Optimize-Options.html\">GCC: Optimize Options</a></p>\n","group":"L1","line":1525},{"id":"content/06_tools_build_debug/04_performance.md:a9053630808902ec:1","question":"<p>(L1, T) Что оптимизатор обычно делает с простыми циклами?</p>\n","answer":"<p><strong>Ответ:</strong> Может выполнять unrolling, vectorization, constant folding и вынос инвариантов, если это сохраняет допустимое поведение.</p>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Optimize-Options.html\">GCC: Optimize Options</a></p>\n","group":"L1","line":1531},{"id":"content/06_tools_build_debug/04_performance.md:24297c01864b5893:1","question":"<p>(L1, D) Почему benchmark без оптимизаций почти бесполезен?</p>\n","answer":"<p><strong>Ответ:</strong> Он часто измеряет debug overhead вместо production path; сравнивать нужно релевантные сборки.</p>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Optimize-Options.html\">GCC: Optimize Options</a></p>\n","group":"L1","line":1537},{"id":"content/06_tools_build_debug/04_performance.md:05647d5e8dd965be:1","question":"<p>(L1, T) Как inline влияет на benchmark?</p>\n","answer":"<p><strong>Ответ:</strong> Убирает call overhead и открывает межфункциональные оптимизации, но может увеличить code size и i-cache pressure.</p>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Optimize-Options.html\">GCC: Optimize Options</a></p>\n","group":"L1","line":1543},{"id":"content/06_tools_build_debug/04_performance.md:a31fead1a65bef9c:1","question":"<p>(L1, D) Почему small function call overhead может исчезнуть после оптимизации?</p>\n","answer":"<p><strong>Ответ:</strong> Inlining или устранение вызова оставляет только полезные инструкции либо полностью удаляет ненаблюдаемое вычисление.</p>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Optimize-Options.html\">GCC: Optimize Options</a></p>\n","group":"L1","line":1549},{"id":"content/06_tools_build_debug/04_performance.md:9ffb0ce7cfb48c82:1","question":"<p>(L2, T) Что такое vectorization и как она влияет на benchmark?</p>\n","answer":"<p><strong>Ответ:</strong> SIMD выполняет несколько операций над элементами одной инструкцией; эффект зависит от данных, alignment и memory bandwidth.</p>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Optimize-Options.html\">GCC: Optimize Options</a></p>\n","group":"L2","line":1558},{"id":"content/06_tools_build_debug/04_performance.md:242ee236d2c68707:1","question":"<p>(L2, D) Почему <code>-march=native</code> может резко изменить результаты?</p>\n","answer":"<p><strong>Ответ:</strong> Разрешает инструкции и tuning текущего CPU; такой бинарник может не работать на более старой машине.</p>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Optimize-Options.html\">GCC: Optimize Options</a></p>\n","group":"L2","line":1564},{"id":"content/06_tools_build_debug/04_performance.md:a3e74d9ecc93732e:1","question":"<p>(L2, D) Как UB может сделать benchmark “быстрым, но бессмысленным”?</p>\n","answer":"<p><strong>Ответ:</strong> Оптимизатор предполагает отсутствие UB и может убрать проверки/циклы; сначала проверяют корректность и sanitizers.</p>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Optimize-Options.html\">GCC: Optimize Options</a></p>\n","group":"L2","line":1570},{"id":"content/06_tools_build_debug/04_performance.md:b888da93a69add94:1","question":"<p>(L2, P) Как проверить, что оптимизатор не упростил benchmark до константы?</p>\n","answer":"<p><strong>Ответ:</strong> Посмотреть <code>objdump -d -C ./bench</code> или compiler output; результат должен зависеть от runtime input и потребляться harness.</p>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Optimize-Options.html\">GCC: Optimize Options</a></p>\n","group":"L2","line":1576},{"id":"content/06_tools_build_debug/04_performance.md:82e560de7b2d16fd:1","question":"<p>(L2, D) Почему release benchmark нужно сопровождать inspection generated code?</p>\n","answer":"<p><strong>Ответ:</strong> Asm подтверждает, что измеряется нужная работа и ожидаемая оптимизация действительно применена.</p>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Optimize-Options.html\">GCC: Optimize Options</a></p>\n","group":"L2","line":1582},{"id":"content/06_tools_build_debug/04_performance.md:bd7d7c303608ebfe:1","question":"<p>(L3, D) Как интерпретировать benchmark, если разные компиляторы дают разный результат?</p>\n","answer":"<p><strong>Ответ:</strong> Сравнить flags, targets и generated code; результат относится к конкретной комбинации compiler/workload, не к языку вообще.</p>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Optimize-Options.html\">GCC: Optimize Options</a></p>\n","group":"L3","line":1591},{"id":"content/06_tools_build_debug/04_performance.md:27637ea11d9ee3ff:1","question":"<p>(L3, D) Почему PGO/LTO могут улучшить одни benchmark'и и ухудшить другие?</p>\n","answer":"<p><strong>Ответ:</strong> Меняют inlining, layout и branch decisions; тренировочный профиль и code-size trade-offs подходят не всем сценариям.</p>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Optimize-Options.html\">GCC: Optimize Options</a></p>\n","group":"L3","line":1597},{"id":"content/06_tools_build_debug/04_performance.md:85bf50e9e3de9319:1","question":"<p>(L3, S) Как выбирать стандартный набор compile flags для perf lab?</p>\n","answer":"<p><strong>Ответ:</strong> Определить supported deployment CPU и production baseline; экспериментальные flags тестировать отдельно, сохраняя correctness checks.</p>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Optimize-Options.html\">GCC: Optimize Options</a></p>\n","group":"L3","line":1603},{"id":"content/06_tools_build_debug/04_performance.md:7cb3e52bdecc269d:1","question":"<p>(L3, D) Как доказывать, что улучшение связано с кодом, а не с изменением flags/toolchain?</p>\n","answer":"<p><strong>Ответ:</strong> Провести A/B с одним toolchain и flags, затем отдельный эксперимент смены окружения.</p>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Optimize-Options.html\">GCC: Optimize Options</a></p>\n","group":"L3","line":1609},{"id":"content/06_tools_build_debug/04_performance.md:b82fd246318455ba:1","question":"<p>(L3, D) Когда необходимо смотреть asm, а не только benchmark numbers?</p>\n","answer":"<p><strong>Ответ:</strong> Когда подозреваются DCE, vectorization, missed inline, UB или неожиданная разница между компиляторами.</p>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Optimize-Options.html\">GCC: Optimize Options</a></p>\n","group":"L3","line":1615},{"id":"content/06_tools_build_debug/04_performance.md:7f0d3c27c9a7bd83:1","question":"<p>(L1, T) Что такое false sharing?</p>\n","answer":"<p><strong>Ответ:</strong> Потоки изменяют независимые объекты одной cache line, вызывая ненужный coherence traffic.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation/perf-c2c.txt\">perf c2c</a></p>\n","group":"L1","line":1626},{"id":"content/06_tools_build_debug/04_performance.md:e80a5772181bf13a:1","question":"<p>(L1, T) Как false sharing связан с cache line?</p>\n","answer":"<p><strong>Ответ:</strong> Coherence работает линиями, поэтому независимость переменных на уровне C++ не означает независимость cache traffic.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation/perf-c2c.txt\">perf c2c</a></p>\n","group":"L1","line":1632},{"id":"content/06_tools_build_debug/04_performance.md:4574c777fe0f0d0d:1","question":"<p>(L1, D) Почему независимые переменные в разных потоках могут мешать друг другу?</p>\n","answer":"<p><strong>Ответ:</strong> Запись требует владения общей линией и может инвалидировать копию у другого CPU.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation/perf-c2c.txt\">perf c2c</a></p>\n","group":"L1","line":1638},{"id":"content/06_tools_build_debug/04_performance.md:98388ea68ebb600e:1","question":"<p>(L1, T) Почему false sharing особенно важен в многопоточном C++ коде?</p>\n","answer":"<p><strong>Ответ:</strong> Per-thread counters и queues часто расположены рядом и активно записываются разными ядрами.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation/perf-c2c.txt\">perf c2c</a></p>\n","group":"L1","line":1644},{"id":"content/06_tools_build_debug/04_performance.md:2d1f671e0a3804e0:1","question":"<p>(L1, P) Какие симптомы могут указывать на false sharing?</p>\n","answer":"<p><strong>Ответ:</strong> Плохое масштабирование, высокая coherence activity и улучшение при разнесении hot writable fields.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation/perf-c2c.txt\">perf c2c</a></p>\n","group":"L1","line":1650},{"id":"content/06_tools_build_debug/04_performance.md:9fc7da38d4e63cc2:1","question":"<p>(L2, D) Как false sharing проявляется в benchmark'ах?</p>\n","answer":"<p><strong>Ответ:</strong> С ростом потоков независимые updates замедляются; контроль с разделёнными cache lines помогает подтвердить причину.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation/perf-c2c.txt\">perf c2c</a></p>\n","group":"L2","line":1659},{"id":"content/06_tools_build_debug/04_performance.md:ca810652f808d646:1","question":"<p>(L2, D) Почему throughput может резко падать при росте числа потоков?</p>\n","answer":"<p><strong>Ответ:</strong> Возможны coherence, locks, bandwidth и oversubscription; false sharing — лишь одна из проверяемых гипотез.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation/perf-c2c.txt\">perf c2c</a></p>\n","group":"L2","line":1665},{"id":"content/06_tools_build_debug/04_performance.md:c08180e5be4e6ae2:1","question":"<p>(L2, P) Как padding помогает бороться с false sharing?</p>\n","answer":"<p><strong>Ответ:</strong> Разносит независимо изменяемые данные по линиям; нужны корректные alignment и размер/stride элементов массива.</p>\n<p><strong>Пример:</strong> C++17, если standard library предоставляет interference constants:</p>\n<pre><code class=\"language-cpp\">#include &lt;atomic&gt;\n#include &lt;new&gt;\n\nstruct alignas(std::hardware_destructive_interference_size) Slot {\n    std::atomic&lt;unsigned long long&gt; count{0};\n};\n// Slot slots[N]: alignment делает stride кратным выбранному alignment.\n</code></pre>\n<p>Константа implementation-defined; она не обещает оптимального layout для каждого deployment CPU. При сравнении binary layout нельзя бездумно менять compiler tuning flags.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation/perf-c2c.txt\">perf c2c</a></p>\n","group":"L2","line":1671},{"id":"content/06_tools_build_debug/04_performance.md:33e4b970bfda15eb:1","question":"<p>(L2, T) Почему array of counters — типичный источник false sharing?</p>\n","answer":"<p><strong>Ответ:</strong> Соседние counters попадают в одну линию, хотя каждый поток пишет только свой элемент.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation/perf-c2c.txt\">perf c2c</a></p>\n","group":"L2","line":1691},{"id":"content/06_tools_build_debug/04_performance.md:a10160af20273aa7:1","question":"<p>(L2, D) Как отличить false sharing от lock contention?</p>\n","answer":"<p><strong>Ответ:</strong> Смотреть blocking stacks и line contention; эксперимент с layout при неизменных locks отделяет гипотезы.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation/perf-c2c.txt\">perf c2c</a></p>\n","group":"L2","line":1697},{"id":"content/06_tools_build_debug/04_performance.md:f1e057dc588ef7d4:1","question":"<p>(L3, D) Как подтвердить false sharing через perf counters и benchmark?</p>\n","answer":"<p><strong>Ответ:</strong> Использовать <code>perf c2c</code> при поддержке PMU и сравнить aligned layout; HITM само по себе не отличает true sharing.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation/perf-c2c.txt\">perf c2c</a></p>\n","group":"L3","line":1706},{"id":"content/06_tools_build_debug/04_performance.md:af7a6bbd7c7196c4:1","question":"<p>(L3, S) Как проектировать per-thread data structures, чтобы избежать false sharing?</p>\n","answer":"<p><strong>Ответ:</strong> Выделять cache-aligned slots с достаточным stride и агрегировать результаты вне hot path; проверять фактический layout.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation/perf-c2c.txt\">perf c2c</a></p>\n","group":"L3","line":1712},{"id":"content/06_tools_build_debug/04_performance.md:dc5d71f5add75109:1","question":"<p>(L3, D) Почему false sharing может появиться после “безобидного” рефакторинга?</p>\n","answer":"<p><strong>Ответ:</strong> Перестановка полей или новый allocator может разместить ранее разнесённые writable данные в одной линии.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation/perf-c2c.txt\">perf c2c</a></p>\n","group":"L3","line":1718},{"id":"content/06_tools_build_debug/04_performance.md:e1b57c1123e44f9c:1","question":"<p>(L3, D) Как NUMA и false sharing вместе ухудшают performance?</p>\n","answer":"<p><strong>Ответ:</strong> Ownership линии перемещается между узлами, добавляя межсокетную latency к coherence traffic.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation/perf-c2c.txt\">perf c2c</a></p>\n","group":"L3","line":1724},{"id":"content/06_tools_build_debug/04_performance.md:180beb5a6831148d:1","question":"<p>(L3, S) Когда padding оправдан, а когда это лишний расход памяти?</p>\n","answer":"<p><strong>Ответ:</strong> Когда доказан выигрыш на горячих writes; учитывать увеличение footprint и ухудшение locality при чтении.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation/perf-c2c.txt\">perf c2c</a></p>\n","group":"L3","line":1730},{"id":"content/06_tools_build_debug/04_performance.md:4c9f3114fbd87f31:1","question":"<p>(L4, S) Как встроить проверку false sharing risks в performance review?</p>\n","answer":"<p><strong>Ответ:</strong> Проверять writers, field placement и array stride у горячих shared структур; измерять сомнительные случаи.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation/perf-c2c.txt\">perf c2c</a></p>\n","group":"L4","line":1739},{"id":"content/06_tools_build_debug/04_performance.md:3c97cdb56c390364:1","question":"<p>(L4, D) Как расследовать production slowdown, вызванный cache-line contention?</p>\n","answer":"<p><strong>Ответ:</strong> Собрать topology, affinity, c2c/PMU samples и адреса lines; сопоставить с полями и проверить layout change.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation/perf-c2c.txt\">perf c2c</a></p>\n","group":"L4","line":1745},{"id":"content/06_tools_build_debug/04_performance.md:3c84216c7488d4e2:1","question":"<p>(L4, S) Какие шаблоны многопоточного дизайна минимизируют false sharing?</p>\n","answer":"<p><strong>Ответ:</strong> Per-thread accumulation, sharding, ownership partitioning и batching сокращают совместные writes.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation/perf-c2c.txt\">perf c2c</a></p>\n","group":"L4","line":1751},{"id":"content/06_tools_build_debug/04_performance.md:04755330fb515cee:1","question":"<p>(L4, D) Как сочетать benchmarking, profiling и code inspection для доказательства false sharing?</p>\n","answer":"<p><strong>Ответ:</strong> Benchmark доказывает эффект, profile локализует линии, inspection показывает независимые поля и подтверждает false sharing.</p>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation/perf-c2c.txt\">perf c2c</a></p>\n","group":"L4","line":1757},{"id":"content/06_tools_build_debug/04_performance.md:e268bffcf2cd2df6:1","question":"<p>(L4, S) Как обучать команду видеть false sharing на уровне структуры данных, а не только профиля?</p>\n","answer":"<p><strong>Ответ:</strong> Рисовать линии с размещёнными полями и назначенными writers; проверять расчёт sizeof/alignment и реальными измерениями.</p>\n<pre><code> **Источник:** [perf c2c](https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation/perf-c2c.txt)\n</code></pre>\n<hr />\n","group":"L4","line":1763},{"id":"content/06_tools_build_debug/04_performance.md:bc5e12e4f9e575e2:1","question":"<p>(L2, D) CPU usage высокий, но throughput низкий: какие основные гипотезы проверишь?</p>\n","answer":"<p><strong>Ответ:</strong> Проверить busy loops, spin contention, cache misses, лишнюю работу и CPU quota; связать CPU profile с throughput.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a>; <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":1776},{"id":"content/06_tools_build_debug/04_performance.md:77dbada9332b62a4:1","question":"<p>(L2, D) После оптимизации алгоритма benchmark улучшился, а система — нет. Почему?</p>\n","answer":"<p><strong>Ответ:</strong> Ускоренный участок не был системным bottleneck либо эффект скрыли I/O, очередь и contention.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a>; <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":1782},{"id":"content/06_tools_build_debug/04_performance.md:5455ce10986e75d4:1","question":"<p>(L2, D) <code>perf</code> показывает hotspot в allocator/STL: как двигаться дальше?</p>\n","answer":"<p><strong>Ответ:</strong> Найти прикладных callers и count/bytes; уменьшать лишние объекты и рост контейнеров до замены allocator.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a>; <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":1788},{"id":"content/06_tools_build_debug/04_performance.md:2c4bc675a5a54827:1","question":"<p>(L2, D) Программа делает много мелких аллокаций: как проверить, что это bottleneck?</p>\n","answer":"<p><strong>Ответ:</strong> Измерить allocation rate, CPU/wait cost, затем bounded reuse/reserve эксперимент с тем же контрактом.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a>; <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":1794},{"id":"content/06_tools_build_debug/04_performance.md:f90ce5e6c121d069:1","question":"<p>(L2, D) С ростом потоков производительность перестала масштабироваться: как расследовать?</p>\n","answer":"<p><strong>Ответ:</strong> Проверить locks, CPU quota, oversubscription, bandwidth, NUMA и false sharing; строить scaling curve.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a>; <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L2","line":1800},{"id":"content/06_tools_build_debug/04_performance.md:5639480cd92870df:1","question":"<p>(L3, D) Flamegraph показывает глубокий стек абстракций, но ни одна функция не выглядит “очевидно плохой”: что это значит?</p>\n","answer":"<p><strong>Ответ:</strong> Стоимость может быть распределена между множеством layers; искать повторную работу, conversions и частоту проходов.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a>; <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":1809},{"id":"content/06_tools_build_debug/04_performance.md:92d9174b14c99f73:1","question":"<p>(L3, D) После перехода на новый компилятор benchmark изменился на 7%: как проверить, реальна ли разница?</p>\n","answer":"<p><strong>Ответ:</strong> Пересобрать обе версии с согласованными flags, чередовать повторы и сравнить asm, variance и system KPIs.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a>; <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":1815},{"id":"content/06_tools_build_debug/04_performance.md:aa029d4b77b3ad0c:1","question":"<p>(L3, D) Есть подозрение на плохую locality данных: какой минимальный план расследования?</p>\n","answer":"<p><strong>Ответ:</strong> Снять baseline/cache events, проверить working set и stride, изменить layout изолированно и сравнить время/misses.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a>; <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":1821},{"id":"content/06_tools_build_debug/04_performance.md:13eb1ea5f8850832:1","question":"<p>(L3, D) Производительность плавает между прогонами без изменений кода: какие источники нестабильности проверишь?</p>\n","answer":"<p><strong>Ответ:</strong> Питание/температуру, фон, scheduler affinity, NUMA, caches, inputs, ASLR и virtualized host contention.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a>; <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":1827},{"id":"content/06_tools_build_debug/04_performance.md:872094f9a7dda91b:1","question":"<p>(L3, D) <code>perf stat</code> показывает много cache-misses и stalled cycles: какие инженерные выводы можно делать, а какие пока нельзя?</p>\n","answer":"<p><strong>Ответ:</strong> Есть признаки stalls и misses, но пока не доказаны причина и полезность layout change; нужны attribution и эксперимент.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a>; <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L3","line":1833},{"id":"content/06_tools_build_debug/04_performance.md:bb6ed253f9f98605:1","question":"<p>(L4, S) Как построить performance engineering process для C/C++ сервиса под Linux?</p>\n","answer":"<p><strong>Ответ:</strong> Определить SLO/budgets, representative workloads, регулярные baselines и расследование регрессий с владельцами и артефактами.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a>; <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L4","line":1842},{"id":"content/06_tools_build_debug/04_performance.md:cd077822513408f7:1","question":"<p>(L4, S) Какие артефакты должны прикладываться к performance regression issue?</p>\n","answer":"<p><strong>Ответ:</strong> Commit/build IDs, hardware/software, flags, workload, raw runs, profiles, метрики и минимальная команда воспроизведения.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a>; <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L4","line":1848},{"id":"content/06_tools_build_debug/04_performance.md:e913b28940e6879c:1","question":"<p>(L4, S) Как стандартизировать benchmark-практику между командами?</p>\n","answer":"<p><strong>Ответ:</strong> Общий harness и metadata schema, классы workload и правила сравнения; сохранять специфику продукта.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a>; <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L4","line":1854},{"id":"content/06_tools_build_debug/04_performance.md:53c53f51a68d1cde:1","question":"<p>(L4, S) Как уменьшить число ложных performance regression alarms?</p>\n","answer":"<p><strong>Ответ:</strong> Стабилизировать окружение, учитывать variance, требовать повторное подтверждение и различать предупреждение и blocking threshold.</p>\n<p><strong>Источник:</strong> <a href=\"https://github.com/google/benchmark/blob/main/docs/user_guide.md\">Google Benchmark: User Guide</a>; <a href=\"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation\">perf tools documentation</a></p>\n","group":"L4","line":1860},{"id":"content/06_tools_build_debug/04_performance.md:e20847f546a36b00:1","question":"<p>(L4, S) Как формализовать правило: “сначала измерь, потом оптимизируй, потом докажи эффект”?</p>\n","answer":"<p><strong>Ответ:</strong> В review прикладывать baseline → гипотезу → изменение → повторный эксперимент с correctness и оценкой side effects.</p>\n<pre><code> **Источник:** [Google Benchmark: User Guide](https://github.com/google/benchmark/blob/main/docs/user_guide.md); [perf tools documentation](https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/tools/perf/Documentation)\n</code></pre>\n<hr />\n","group":"L4","line":1866}];
